const COURSES = [{"id": "digital", "title": "Digital Experience", "symbol": "01", "description": "Sistemas numéricos, portas lógicas e expressões booleanas.", "note": "Trilha dos quatro tópicos enviados, com exercícios autorais. As próximas aulas serão acrescentadas quando você tiver os materiais liberados.", "url": null}, {"id": "algoritmos", "title": "Fundamentos de Algoritmos", "symbol": "⌘", "description": "Do primeiro algoritmo a funções, coleções e arquivos.", "note": "Lições introdutórias dos temas das 13 aulas de teoria disponíveis. Os PDFs foram reunidos; aprofundamentos e mais exercícios serão acrescentados progressivamente.", "url": "https://docs.python.org/3/tutorial/"}, {"id": "dados", "title": "Banco de Dados", "symbol": "▦", "description": "Dos modelos ER e relacional às operações de álgebra e SQL.", "note": "Trilha introdutória dos seis blocos de conteúdo disponíveis: MER, cardinalidade e estendido, modelo relacional, álgebra relacional, SQL DDL e DML — Parte 1. Exemplos e exercícios autorais para estudar; materiais e atividades originais estão nos links abaixo.", "url": "https://www.postgresql.org/docs/current/tutorial-sql.html", "resources": [{"title": "Introdução e MER", "url": "https://moodle.fei.edu.br/course/section.php?id=2416"}, {"title": "Cardinalidade e MER estendido", "url": "https://moodle.fei.edu.br/course/section.php?id=4332"}, {"title": "Modelo Relacional e estendido", "url": "https://moodle.fei.edu.br/course/section.php?id=2417"}, {"title": "Álgebra Relacional", "url": "https://moodle.fei.edu.br/course/section.php?id=2422"}, {"title": "SQL: DDL", "url": "https://moodle.fei.edu.br/course/section.php?id=2418"}, {"title": "SQL: DML — Parte 1", "url": "https://moodle.fei.edu.br/course/section.php?id=5921"}, {"title": "Projeto", "url": "https://moodle.fei.edu.br/course/section.php?id=2426"}, {"title": "Exercícios MER — Extras", "url": "https://moodle.fei.edu.br/course/section.php?id=2427"}], "resourceNote": "Projeto e Extras foram consultados, mas não mostraram conteúdo específico nesta sessão. Os links permitem verificar o que estiver liberado no Moodle."}, {"id": "web", "title": "Programação Full Stack", "symbol": "⌥", "description": "HTML, CSS, layout e primeiras funções em JavaScript.", "note": "Primeiras lições para as seis aulas liberadas: HTML, CSS e JavaScript. Conteúdos posteriores ainda não foram adicionados à trilha.", "url": "https://developer.mozilla.org/en-US/docs/Learn_web_development"}];
LESSONS.forEach(l=>l.course="digital");
LESSONS.push(...[{"course": "digital", "id": "fracoes", "group": "02 · Conversões e cálculos", "title": "Binários com parte fracionária", "time": 6, "source": "Complemento didático dos tópicos presentes nos PDFs enviados", "body": "<p>À direita da vírgula, os valores das posições são <strong>1/2, 1/4, 1/8…</strong> Cada passo divide o valor por 2.</p><div class=\"example\">0,11₂ = 1/2 + 1/4 = 0,75₁₀.</div><p>Para converter uma fração decimal em binário, multiplique a fração por 2. Anote a parte inteira e repita com a nova parte fracionária.</p><div class=\"example\">0,25 × 2 = 0,5 → bit 0.<br>0,5 × 2 = 1,0 → bit 1.<br>Resultado: 0,01₂. Os bits são lidos na ordem em que aparecem.</div>", "qs": [{"q": "Quanto vale 0,101₂ em decimal?", "why": "Some 1/2 + 0/4 + 1/8 = 0,5 + 0,125 = 0,625. A terceira casa fracionária vale 1/8, não 1/3.", "h": "Use 0,5; 0,25; 0,125 para as três posições.", "o": ["0.625"], "a": 0}, {"q": "Qual é a representação binária de 0,75₁₀?", "o": ["0,11₂", "0,01₂", "0,10₂"], "a": 0, "why": "0,75 × 2 = 1,5 (bit 1). Depois, 0,5 × 2 = 1,0 (bit 1). Resultado 0,11₂. Não inverta a ordem dos bits fracionários.", "h": "Multiplique a parte fracionária por 2 duas vezes."}]}, {"course": "digital", "id": "tabela-expressao", "group": "04 · Expressões booleanas", "title": "Da tabela-verdade à expressão", "time": 6, "source": "Complemento didático dos tópicos presentes nos PDFs enviados", "body": "<p>Para obter uma expressão a partir da tabela, observe as linhas em que a saída é 1. Cada linha vira um termo AND. Uma entrada 0 entra negada; uma entrada 1 entra sem negação. Una os termos com OR.</p><div class=\"example\">Se apenas A=0, B=1 produz saída 1, o termo é ¬A · B.</div><p>Quando várias linhas produzem 1, use a soma dos produtos. Para A,B = 01 e 11, obtemos ¬A·B + A·B. Os dois termos compartilham B.</p>", "qs": [{"q": "A saída é 1 apenas quando A=1 e B=0. Qual expressão representa a função?", "o": ["A · ¬B", "¬A · B", "A + B"], "a": 0, "why": "A deve valer 1, então aparece sem negação. B deve valer 0, então aparece como ¬B. Junte as condições por AND: A · ¬B.", "h": "A condição da linha precisa ser verdadeira para as duas entradas ao mesmo tempo."}, {"q": "Qual expressão simplificada dá 1 nas linhas 01 e 11?", "o": ["A", "B", "¬B"], "a": 1, "why": "Nas duas linhas, B é sempre 1 e A pode variar. A saída depende somente de B.", "h": "Qual entrada permanece igual nas duas linhas?"}]}, {"course": "algoritmos", "id": "alg-sequencia", "group": "01 · Primeiros algoritmos", "title": "Sequência, entrada e saída", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Um algoritmo é uma sequência de passos para resolver um problema. <strong>Entrada</strong> é o que recebemos; <strong>processamento</strong> é o que fazemos; <strong>saída</strong> é o resultado.</p><div class=\"example\">Receber dois preços → somar → mostrar o total.</div><p>Em lógica sequencial, cada instrução usa o estado produzido pelas anteriores.</p><pre><code>x = 3\nx = x + 2\nprint(x)</code></pre>", "qs": [{"q": "Nesse exemplo, quais são as entradas?", "o": ["Os dois preços", "O total já calculado", "A operação de soma"], "a": 0, "why": "Os preços entram no cálculo. A soma é o processamento e o total é a saída.", "h": "Pergunte quais dados precisamos conhecer antes de começar."}, {"q": "Qual número será mostrado?", "why": "x começa com 3. A instrução seguinte guarda 3 + 2 em x. print mostra o valor atual, 5.", "h": "A atribuição substitui o valor anterior de x.", "o": ["5"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-variaveis", "group": "01 · Primeiros algoritmos", "title": "Variáveis, tipos e contas", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Uma variável tem um nome e guarda um valor. Em Python, = atribui e == compara. Multiplicação tem precedência sobre adição.</p><pre><code>total = 2 + 3 * 4</code></pre><p>input() lê texto. Para usar uma idade em uma conta, converta o texto para um número com int().</p><pre><code>idade = int(input(&quot;Idade: &quot;))</code></pre>", "qs": [{"q": "Qual é o valor de total?", "why": "Primeiro 3 * 4 = 12. Depois 2 + 12 = 14. Para somar 2 + 3 primeiro, seriam necessários parênteses.", "h": "Faça a multiplicação antes da soma.", "o": ["14"], "a": 0}, {"q": "Por que usamos int() nesse exemplo?", "o": ["Para converter o texto em inteiro", "Para imprimir uma mensagem", "Para repetir a leitura dez vezes"], "a": 0, "why": "input() retorna texto. int() tenta transformar esse texto em um número inteiro. Um texto como \"abc\" não pode ser convertido dessa forma.", "h": "O valor precisa participar de uma conta numérica."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-condicoes", "group": "02 · Decisões", "title": "if, else e comparações", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>if executa um bloco quando a condição é verdadeira; else executa a alternativa. A indentação mostra quais instruções pertencem ao bloco.</p><pre><code>nota = 7\nif nota &gt;= 6:\n    print(&quot;Aprovada&quot;)\nelse:\n    print(&quot;Revisar&quot;)</code></pre><p>Os operadores &gt;, &lt;, &gt;=, &lt;=, == e != comparam valores. == testa igualdade; = atribui.</p>", "qs": [{"q": "O que o programa mostra?", "o": ["Aprovada", "Revisar", "As duas mensagens"], "a": 0, "why": "7 >= 6 é verdadeiro. Apenas o bloco do if é executado. O else é a alternativa, não uma etapa adicional.", "h": "Compare 7 com 6."}, {"q": "Qual expressão testa se x é igual a 10?", "o": ["x == 10", "x = 10", "x != 10"], "a": 0, "why": "x == 10 compara. x = 10 atribui o valor 10. x != 10 testa se são diferentes.", "h": "O teste de igualdade usa dois sinais de igual."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-logicos", "group": "02 · Decisões", "title": "and, or e not", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Em condições booleanas de Python: and exige as duas condições verdadeiras; or aceita pelo menos uma; not inverte o resultado.</p><pre><code>idade = 20\ntem_documento = False\npode_entrar = idade &gt;= 18 and tem_documento</code></pre><p>Use parênteses para deixar claras as combinações de condições.</p><pre><code>(5 &gt; 3) or (2 &gt; 8)</code></pre>", "qs": [{"q": "Qual é o valor de pode_entrar?", "o": ["False", "True"], "a": 0, "why": "A idade satisfaz a condição, mas tem_documento é False. and exige que as duas condições sejam verdadeiras.", "h": "Uma das condições é falsa."}, {"q": "Qual é o resultado?", "o": ["True", "False"], "a": 0, "why": "5 > 3 é True. Em or, uma condição verdadeira já torna o resultado True.", "h": "or precisa de pelo menos uma condição verdadeira."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-repeticao", "group": "03 · Repetições", "title": "for, while e contadores", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>for percorre os itens de uma sequência. range(4) produz os inteiros 0, 1, 2 e 3: o limite final não entra.</p><pre><code>for i in range(4):\n    print(i)</code></pre><p>while repete enquanto a condição for verdadeira. Atualize a variável usada na condição para permitir o término.</p><pre><code>x = 0\nwhile x &lt; 3:\n    x = x + 1\nprint(x)</code></pre>", "qs": [{"q": "Quantas vezes print será executado?", "why": "range(4) tem quatro valores: 0, 1, 2 e 3. Começar em zero não acrescenta uma quinta repetição.", "h": "Liste os valores antes de contar.", "o": ["4"], "a": 0}, {"q": "Qual é o valor mostrado ao final?", "why": "x passa por 1, 2 e 3. Quando chega a 3, x < 3 é falso e o laço termina. print está fora do laço.", "h": "A condição é verificada novamente após cada incremento.", "o": ["3"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-aninhados", "group": "03 · Repetições", "title": "Laços aninhados", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Um laço dentro de outro roda completamente para cada repetição externa.</p><pre><code>for linha in range(2):\n    for coluna in range(3):\n        print(&quot;*&quot;)</code></pre><p>Um acumulador guarda um resultado que cresce a cada repetição. Inicialize antes do laço.</p><pre><code>soma = 0\nfor n in [1, 2, 3]:\n    soma = soma + n\nprint(soma)</code></pre>", "qs": [{"q": "Quantos asteriscos serão mostrados?", "why": "O laço interno roda 3 vezes para cada uma das 2 repetições externas. Total: 2 × 3 = 6.", "h": "Multiplique as quantidades de repetições.", "o": ["6"], "a": 0}, {"q": "Qual é o resultado final?", "why": "soma vai de 0 para 1, depois para 3 e finalmente para 6. A variável não é reiniciada dentro do laço.", "h": "Some os itens da lista.", "o": ["6"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-funcoes", "group": "04 · Organizando programas", "title": "Funções, parâmetros e retorno", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Uma função reúne instruções reutilizáveis. Parâmetros recebem dados; return entrega um resultado a quem chamou.</p><pre><code>def dobro(n):\n    return n * 2\n\nprint(dobro(4))</code></pre><p>print mostra algo na tela. return fornece um valor ao restante do programa. Uma função sem return explícito retorna None.</p>", "qs": [{"q": "Qual valor será mostrado?", "why": "A chamada dobro(4) usa n=4. return devolve 4 * 2 = 8.", "h": "Substitua n pelo argumento da chamada.", "o": ["8"], "a": 0}, {"q": "Qual instrução deve fornecer o resultado de uma função para outra conta?", "o": ["return resultado", "print(resultado)", "input(resultado)"], "a": 0, "why": "return entrega o valor à expressão que chamou a função. print apenas escreve na saída e não substitui esse retorno.", "h": "O chamador precisa receber um valor."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-listas-tuplas", "group": "05 · Coleções", "title": "Listas e tuplas", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Listas armazenam vários itens em ordem. O primeiro índice é <strong>0</strong>.</p><pre><code>notas = [7, 8, 9]\nprint(notas[1])</code></pre><p>Uma lista pode ter itens substituídos, adicionados ou removidos. Uma tupla não permite substituir seus itens depois de criada.</p><pre><code>lista = [1, 2]\ntupla = (1, 2)</code></pre>", "qs": [{"q": "Qual número aparece?", "why": "O índice 0 contém 7; o índice 1 contém 8. Não confunda índice com posição contada a partir de 1.", "h": "O segundo item tem índice 1.", "o": ["8"], "a": 0}, {"q": "Qual atribuição é permitida?", "o": ["lista[0] = 9", "tupla[0] = 9"], "a": 0, "why": "Listas são mutáveis. Tuplas não permitem atribuição a posições como tupla[0] = 9.", "h": "Escolha a coleção que pode ser alterada."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-listas", "group": "05 · Coleções", "title": "Percorrendo e alterando listas", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>append adiciona um item ao final. len informa a quantidade de itens.</p><pre><code>itens = [2, 4]\nitens.append(6)\nprint(len(itens))</code></pre><p>Ao percorrer uma lista, a variável do laço recebe cada item em ordem.</p><pre><code>total = 0\nfor valor in [2, 4, 6]:\n    total += valor\nprint(total)</code></pre>", "qs": [{"q": "Qual quantidade aparece?", "why": "A lista passa a ser [2, 4, 6], com três itens. len conta itens, não soma seus valores.", "h": "Conte os itens depois do append.", "o": ["3"], "a": 0}, {"q": "Qual é o total?", "why": "total acumula 2 + 4 + 6 = 12. += soma ao valor atual e guarda o resultado.", "h": "Some os valores, sem usar os índices.", "o": ["12"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-matrizes", "group": "05 · Coleções", "title": "Listas aninhadas e matrizes", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Uma matriz pode ser uma lista de linhas. Use matriz[linha][coluna], com índices começando em zero.</p><pre><code>m = [[1, 2], [3, 4]]\nprint(m[1][0])</code></pre><p>Uma matriz com 3 linhas e 4 colunas tem 3 × 4 posições. Dois laços ajudam a visitar todas elas.</p>", "qs": [{"q": "Qual número será mostrado?", "why": "m[1] seleciona a segunda linha, [3, 4]. O índice [0] seleciona seu primeiro item, 3.", "h": "Selecione a linha primeiro e a coluna depois.", "o": ["3"], "a": 0}, {"q": "Quantas posições tem uma matriz com 2 linhas e 5 colunas?", "why": "São cinco posições em cada uma das duas linhas: 2 × 5 = 10.", "h": "Multiplique linhas por colunas.", "o": ["10"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-dicionarios", "group": "05 · Coleções", "title": "Dicionários: chaves e valores", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Dicionários associam chaves a valores. Em vez de buscar por posição, usamos uma chave.</p><pre><code>aluna = {&quot;nome&quot;: &quot;Ana&quot;, &quot;idade&quot;: 19}\nprint(aluna[&quot;idade&quot;])</code></pre><p>get permite buscar uma chave e fornecer um valor padrão quando ela não existir.</p><pre><code>dados = {&quot;nome&quot;: &quot;Ana&quot;}\nprint(dados.get(&quot;curso&quot;, &quot;Não informado&quot;))</code></pre>", "qs": [{"q": "Qual é o valor mostrado?", "why": "A chave \"idade\" está associada ao valor 19. O nome da chave não é o valor armazenado.", "h": "Procure o valor à direita da chave idade.", "o": ["19"], "a": 0}, {"q": "O que aparece?", "o": ["Não informado", "curso", "Ana"], "a": 0, "why": "A chave \"curso\" não existe. get devolve o valor padrão \"Não informado\".", "h": "Verifique se a chave está no dicionário."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-arquivos", "group": "06 · Dados e interfaces", "title": "Leitura e escrita de arquivos", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>open abre um arquivo. O modo \"r\" lê; \"w\" escreve substituindo o conteúdo; \"a\" acrescenta ao final. with ajuda a fechar o arquivo ao sair do bloco.</p><p>read lê o conteúdo do arquivo. Aqui o arquivo é aberto apenas para leitura.</p><pre><code>with open(&quot;notas.txt&quot;, &quot;r&quot;, encoding=&quot;utf-8&quot;) as arquivo:\n    texto = arquivo.read()</code></pre>", "qs": [{"q": "Qual modo acrescenta conteúdo sem apagar o anterior?", "o": ["a", "w", "r"], "a": 0, "why": "O modo a significa append: acrescentar. w pode apagar o conteúdo anterior; r é para leitura.", "h": "Pense em append."}, {"q": "Onde fica o conteúdo lido?", "o": ["Na variável texto", "No nome do arquivo", "Em uma nova pasta"], "a": 0, "why": "read() retorna o conteúdo, que é atribuído a texto. A leitura não cria uma pasta nem altera o nome do arquivo.", "h": "Observe a variável à esquerda da atribuição."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "algoritmos", "id": "alg-strings-modulos", "group": "06 · Dados e interfaces", "title": "Strings, módulos e interfaces", "time": 9, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>Strings são sequências de caracteres. Também usam índices a partir de zero. len conta seus caracteres.</p><pre><code>texto = &quot;FEI&quot;\nprint(len(texto))</code></pre><p>Um módulo organiza funções reutilizáveis. import permite usar esse código.</p><pre><code>import math\nprint(math.sqrt(16))</code></pre><p>Em uma interface gráfica, eventos como cliques disparam funções associadas aos controles.</p>", "qs": [{"q": "Quantos caracteres são contados?", "why": "A string contém F, E e I: três caracteres.", "h": "Conte as letras da string.", "o": ["3"], "a": 0}, {"q": "Qual é o valor numérico do resultado?", "why": "sqrt calcula a raiz quadrada. A raiz de 16 é 4. Python mostra 4.0, que é numericamente igual a 4.", "h": "Qual número multiplicado por si mesmo resulta em 16?", "o": ["4"], "a": 0}, {"q": "Ao clicar em um botão “Calcular”, qual comportamento faz sentido?", "o": ["Executar a função de cálculo e atualizar o resultado", "Reiniciar o computador", "Alterar todos os arquivos automaticamente"], "a": 0, "why": "Um botão normalmente aciona uma função ligada ao evento de clique. Essa função lê entradas, calcula e atualiza a interface.", "h": "Associe o clique a uma função específica."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "dados", "id": "db-entidades", "group": "01 · Modelo Entidade-Relacionamento", "title": "Entidades, atributos e relacionamentos", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>Uma entidade representa algo sobre o qual guardamos dados. Atributos descrevem essa entidade. Relacionamentos ligam entidades.</p><div class=\"example\">Aluno tem nome e matrícula. Aluno realiza matrícula em Disciplina.</div><p>Um modelo evita misturar conceitos diferentes. Clientes e pedidos são entidades ligadas por um relacionamento.</p>", "qs": [{"q": "Nesse contexto, qual é um atributo de Aluno?", "o": ["nome", "Disciplina", "cursa"], "a": 0, "why": "nome descreve Aluno. Disciplina é outra entidade; cursa descreve uma relação.", "h": "Procure uma característica da entidade."}, {"q": "Qual frase expressa um relacionamento?", "o": ["Cliente faz Pedido", "Cliente tem nome", "Pedido tem data"], "a": 0, "why": "Cliente faz Pedido liga duas entidades. As outras frases descrevem atributos.", "h": "Busque uma ligação entre dois tipos de objeto."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "web", "id": "web-html", "group": "02 · Front-end", "title": "HTML: estrutura e significado", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>HTML organiza e dá significado ao conteúdo. Elementos usam tags como &lt;h1&gt; para título principal e &lt;p&gt; para parágrafo.</p><pre><code>&lt;h1&gt;Minha página&lt;/h1&gt;\n&lt;p&gt;Bem-vinda!&lt;/p&gt;</code></pre><p>Links usam o elemento a e o atributo href para definir o destino.</p><pre><code>&lt;a href=&quot;https://exemplo.com&quot;&gt;Visitar&lt;/a&gt;</code></pre>", "qs": [{"q": "Qual elemento representa um parágrafo?", "o": ["<p>", "<h1>", "<img>"], "a": 0, "why": "p identifica um parágrafo. h1 identifica um título e img insere uma imagem.", "h": "Pense na inicial de paragraph."}, {"q": "Qual atributo guarda o endereço do link?", "o": ["href", "class", "alt"], "a": 0, "why": "href indica o destino. class identifica classes de estilo; alt é texto alternativo em imagens.", "h": "Observe o atributo que contém o endereço."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "web", "id": "web-css", "group": "02 · Front-end", "title": "CSS: seletores e aparência", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>CSS controla a apresentação. Um seletor escolhe elementos, e declarações definem propriedades.</p><pre><code>.destaque {\n  color: green;\n}</code></pre><p>color altera a cor do texto. background-color altera o fundo. padding é espaço interno; margin é espaço externo.</p>", "qs": [{"q": "Quais elementos recebem essa regra?", "o": ["Os que têm class=\"destaque\"", "Somente elementos com id=\"destaque\"", "Todos os parágrafos, sempre"], "a": 0, "why": "O ponto antes do nome seleciona uma classe. Para id, usamos #.", "h": "Ponto indica classe; # indica id."}, {"q": "Qual propriedade cria espaço dentro da borda?", "o": ["padding", "margin", "color"], "a": 0, "why": "padding fica entre o conteúdo e a borda. margin fica do lado de fora da borda.", "h": "Espaço interno é padding."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "web", "id": "web-layout", "group": "02 · Front-end", "title": "Layout e telas pequenas", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>Flexbox distribui elementos em uma dimensão, como uma linha ou coluna. Grid organiza linhas e colunas.</p><pre><code>.linha { display: flex; gap: 12px; }</code></pre><p>Media queries aplicam regras sob condições, como largura máxima da tela. Isso ajuda a adaptar a interface ao celular.</p><pre><code>@media (max-width: 600px) {\n  .colunas { grid-template-columns: 1fr; }\n}</code></pre>", "qs": [{"q": "Qual é a função de gap nesse layout?", "o": ["Criar espaço entre os itens", "Alterar o texto dos itens", "Enviar dados ao servidor"], "a": 0, "why": "gap define o espaçamento entre os itens do layout.", "h": "Observe o valor em pixels."}, {"q": "Quando essa regra é aplicada?", "o": ["Quando a largura é de até 600px", "Somente em telas maiores que 600px", "Somente quando existe mouse"], "a": 0, "why": "max-width estabelece um limite máximo inclusivo. A regra vale em 600px ou menos.", "h": "max significa máximo."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "web", "id": "web-js", "group": "02 · Front-end", "title": "JavaScript: valores e condições", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>JavaScript adiciona comportamento à página. let declara uma variável que pode receber outro valor.</p><pre><code>let pontos = 2;\npontos = pontos + 3;</code></pre><p>=== compara valor e tipo sem converter automaticamente. Uma string como \"5\" e o número 5 têm tipos diferentes.</p><pre><code>5 === &quot;5&quot;</code></pre>", "qs": [{"q": "Quanto vale pontos ao final?", "why": "A segunda atribuição usa 2 + 3 e guarda 5. A variável não mantém simultaneamente os dois valores.", "h": "Atualize o valor da variável.", "o": ["5"], "a": 0}, {"q": "Qual é o resultado?", "o": ["false", "true"], "a": 0, "why": "O número 5 e o texto \"5\" têm tipos diferentes, portanto a igualdade estrita é false.", "h": "As aspas indicam uma string."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "web", "id": "web-dom", "group": "02 · Front-end", "title": "DOM e eventos", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>O DOM representa os elementos da página para o JavaScript. Uma função pode localizar um elemento e atualizar seu texto.</p><pre><code>const titulo = document.getElementById(&quot;titulo&quot;);\ntitulo.textContent = &quot;Olá!&quot;;</code></pre><p>Um listener associa uma função a um evento, como click.</p><pre><code>botao.addEventListener(&quot;click&quot;, calcular);</code></pre>", "qs": [{"q": "O que textContent altera?", "o": ["O texto do elemento", "O endereço do servidor", "A senha do navegador"], "a": 0, "why": "textContent define conteúdo textual. Ele não muda a localização do servidor nem credenciais.", "h": "A propriedade se refere ao conteúdo do elemento."}, {"q": "Quando calcular será chamada nesse caso?", "o": ["Quando o botão for clicado", "Somente quando o computador iniciar", "A cada segundo, automaticamente"], "a": 0, "why": "A função é associada ao evento click do botão. O código não cria um temporizador.", "h": "Veja o nome do evento."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "web", "id": "web-formularios", "group": "02 · Front-end", "title": "Formulários e validação", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>Formulários coletam dados. label identifica um campo; input permite digitação; required solicita preenchimento.</p><p>Validação no navegador dá retorno rápido. O servidor também precisa validar os dados, pois uma requisição pode chegar sem passar pela interface.</p>", "qs": [{"q": "Para que serve um label associado ao campo?", "o": ["Explicar e identificar o campo para quem o usa", "Criptografar o valor automaticamente", "Substituir o servidor"], "a": 0, "why": "O label dá um nome compreensível ao controle e ajuda na acessibilidade.", "h": "O usuário precisa saber o que preencher."}, {"q": "Onde deve existir validação de dados recebidos?", "o": ["No servidor também", "Somente no navegador", "Somente no arquivo CSS"], "a": 0, "why": "O servidor não pode confiar apenas em verificações do cliente. Dados podem chegar por outros clientes ou requisições diretas.", "h": "O recebimento pode ocorrer fora do formulário normal."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "dados", "id": "db-atributos", "group": "01 · Modelo Entidade-Relacionamento", "title": "Atributos simples e compostos", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>Um atributo descreve uma entidade. Ele é <strong>simples</strong> quando não é dividido no modelo. É <strong>composto</strong> quando reunimos partes, como endereço dividido em rua, número e cidade.</p><p>A classificação depende do que o sistema precisa guardar. Um nome pode ser tratado como um único texto ou dividido em partes, se as regras exigirem.</p>", "qs": [{"q": "Qual atributo é composto nesse exemplo?", "o": ["Endereço com rua, número e cidade", "Um código indivisível", "Uma nota numérica"], "a": 0, "why": "O endereço pode ser dividido em partes relevantes para o modelo. Ser texto ou número não determina sozinho se um atributo é composto.", "h": "Procure um atributo que se divide em partes."}, {"q": "Se o sistema guarda nome e sobrenome separadamente dentro de Nome, como esse atributo é modelado?", "o": ["Composto", "Multivalorado obrigatoriamente", "Derivado obrigatoriamente"], "a": 0, "why": "Nome tem partes identificáveis no modelo, por isso é composto. Isso não significa que uma pessoa tenha vários nomes registrados nesse atributo.", "h": "Dividir em partes é diferente de permitir vários valores."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "dados", "id": "db-multivalorados", "group": "01 · Modelo Entidade-Relacionamento", "title": "Atributos multivalorados e derivados", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>Um atributo de valor único tem um valor por ocorrência. Um atributo <strong>multivalorado</strong> pode ter vários valores para a mesma ocorrência.</p><div class=\"example\">Uma pessoa pode ter os idiomas {português, inglês}. Idiomas é multivalorado nesse modelo.</div><p>Um atributo <strong>armazenado</strong> é guardado diretamente. Um atributo <strong>derivado</strong> pode ser calculado a partir de outros dados.</p><div class=\"example\">Data de nascimento é armazenada. Idade pode ser calculada com ela e a data atual.</div>", "qs": [{"q": "Um cliente pode cadastrar vários telefones. Como classificar Telefone?", "o": ["Multivalorado", "Derivado", "Sempre composto"], "a": 0, "why": "A mesma pessoa pode ter mais de um valor de telefone. Isso caracteriza multivaloração. Vários dígitos em um telefone não significam vários telefones.", "h": "Conte os valores por cliente, não os caracteres."}, {"q": "Nesse exemplo, qual atributo é derivado?", "o": ["Idade", "Data de nascimento"], "a": 0, "why": "Idade é obtida por cálculo. Data de nascimento é o dado usado nesse cálculo.", "h": "Qual informação muda com a passagem do tempo?"}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "dados", "id": "db-dominio-null", "group": "01 · Modelo Entidade-Relacionamento", "title": "Domínios, NULL e chaves", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>O <strong>tipo</strong> indica a natureza de um valor, como inteiro ou texto. O <strong>domínio</strong> estabelece quais valores são aceitos.</p><div class=\"example\">Uma nota pode ser numérica e ter domínio de 0 a 10.</div><p>NULL representa ausência de valor. Ele é diferente de zero ou de um texto vazio. Uma chave primária identifica cada registro e não aceita NULL.</p>", "qs": [{"q": "Se o domínio da nota é de 0 a 10, qual valor é inválido?", "o": ["11", "7", "0"], "a": 0, "why": "11 está fora do intervalo permitido. Zero está dentro do domínio; não significa que o valor esteja ausente.", "h": "Compare cada valor com os limites 0 e 10."}, {"q": "Qual propriedade uma chave primária deve ter?", "o": ["Identificar cada registro de forma única, sem NULL", "Aceitar valores repetidos em todos os registros", "Ser sempre o nome da pessoa"], "a": 0, "why": "A identificação precisa ser única e estar presente. Nomes podem se repetir e não são automaticamente boas chaves.", "h": "Cada ocorrência precisa de uma identificação distinta."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "dados", "id": "db-fortes-fracas", "group": "01 · Modelo Entidade-Relacionamento", "title": "Entidades fortes e fracas", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>Uma entidade forte tem uma chave que a identifica. Uma entidade fraca depende de uma entidade proprietária para sua identificação completa e existência no modelo.</p><div class=\"example\">Um dependente de funcionário pode ser identificado pela combinação do funcionário e de um identificador local do dependente.</div><p>Uma chave composta usa mais de um atributo. No exemplo, funcionário_id junto de dependente_numero pode identificar um dependente.</p>", "qs": [{"q": "No exemplo, por que o dependente é uma entidade fraca?", "o": ["Sua identificação completa depende do funcionário", "Porque tem poucos atributos", "Porque seu nome é curto"], "a": 0, "why": "A dependência de identificação caracteriza a entidade fraca. O número de atributos e o tamanho do nome não determinam isso.", "h": "Observe de quem vem parte da identificação."}, {"q": "Qual combinação identifica um dependente nesse modelo?", "o": ["funcionário_id e dependente_numero", "Apenas a idade", "Apenas um nome que pode se repetir"], "a": 0, "why": "O identificador local pode repetir entre funcionários diferentes. A combinação com funcionário_id torna a identificação completa.", "h": "Inclua a identificação do proprietário."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "dados", "id": "db-relacionamentos", "group": "01 · Modelo Entidade-Relacionamento", "title": "Tipos de relacionamento", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>Relacionamentos ligam entidades e costumam ser descritos por ações. Um relacionamento binário envolve dois tipos de entidade; um ternário envolve três.</p><div class=\"example\">Funcionário trabalha em Projeto: binário.<br>Fornecedor fornece Peça para Projeto: ternário.</div><p>Em um relacionamento recursivo, um mesmo tipo de entidade participa em papéis diferentes.</p><div class=\"example\">Funcionário supervisiona Funcionário: um é supervisor e o outro é supervisionado.</div>", "qs": [{"q": "Quantos tipos de entidade participam de um relacionamento ternário?", "o": ["Três", "Dois", "Um"], "a": 0, "why": "Ternário significa que três tipos de entidade participam da mesma associação.", "h": "Conte os tipos envolvidos, não os atributos."}, {"q": "Qual exemplo é recursivo?", "o": ["Funcionário supervisiona Funcionário", "Cliente compra Produto", "Aluno cursa Disciplina"], "a": 0, "why": "O mesmo tipo, Funcionário, aparece nos dois papéis. As outras relações ligam tipos diferentes.", "h": "Procure a mesma entidade exercendo papéis diferentes."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "dados", "id": "db-participacao", "group": "01 · Modelo Entidade-Relacionamento", "title": "Participação total e parcial", "time": 6, "source": "Moodle · Tópico 2: Modelo Entidade-Relacionamento · leitura online dos 42 slides; exercícios autorais", "body": "<p>A participação é <strong>total</strong> quando toda ocorrência deve participar do relacionamento. É <strong>parcial</strong> quando a participação não é obrigatória para todas.</p><div class=\"example\">Suponha que todo empréstimo deva ser realizado por um aluno, mas um aluno possa existir sem realizar empréstimos.</div><p>Analise cada lado separadamente. Um relacionamento pode ter participação total em um lado e parcial no outro.</p>", "qs": [{"q": "Qual é a participação de Empréstimo no relacionamento com Aluno?", "o": ["Total", "Parcial"], "a": 0, "why": "Todo empréstimo precisa estar ligado a um aluno, então sua participação é total. Isso não obriga todo aluno a ter empréstimos.", "h": "Leia a obrigação do lado do empréstimo."}, {"q": "Na mesma regra, qual é a participação de Aluno?", "o": ["Parcial", "Total"], "a": 0, "why": "Um aluno pode estar cadastrado sem ter feito empréstimo. Portanto, sua participação é parcial.", "h": "Um aluno pode existir sem participar?"}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12799"}, {"course": "algoritmos", "id": "alg-testemesa", "group": "01 · Primeiros algoritmos", "title": "Teste de mesa e pseudocódigo", "time": 6, "source": "Moodle · Fundamentos de Algoritmos · teoria; exercícios autorais de introdução", "body": "<p>O teste de mesa simula um algoritmo passo a passo. Registre os valores das variáveis depois de cada instrução, sem executar no computador.</p><pre><code>x = 2\ny = x + 3\nx = y * 2</code></pre><p>Um algoritmo pode ser expresso em pseudocódigo, fluxograma ou linguagem de programação. O pseudocódigo ajuda a organizar a lógica antes da sintaxe de uma linguagem.</p>", "qs": [{"q": "Qual é o valor final de x?", "why": "x começa em 2. y recebe 2 + 3 = 5. Depois x recebe 5 * 2 = 10. A alteração de x não faz y ser recalculado.", "h": "Atualize uma variável por instrução.", "o": ["10"], "a": 0}, {"q": "Qual sequência representa somar dois números?", "o": ["Ler A e B → calcular A + B → mostrar resultado", "Mostrar resultado → ler A → esquecer B", "Somar sem conhecer os valores → encerrar"], "a": 0, "why": "Primeiro recebemos as entradas, depois processamos e finalmente apresentamos a saída.", "h": "Organize entrada, processamento e saída."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=2380"}, {"course": "web", "id": "web-posicionamento", "group": "02 · Front-end", "title": "CSS: posicionamento e camadas", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>position: relative mantém o elemento no fluxo e permite deslocá-lo a partir da posição original. position: absolute o retira do fluxo e usa seu bloco de referência para posicionamento.</p><div class=\"example\">Um contêiner com position: relative pode servir de referência para um filho com position: absolute.</div><p>position: fixed normalmente usa a janela de visualização como referência. z-index ajuda a definir a ordem de sobreposição, dentro das regras de empilhamento.</p>", "qs": [{"q": "Qual valor de position mantém o elemento no fluxo, permitindo deslocamento relativo?", "o": ["relative", "absolute", "fixed"], "a": 0, "why": "relative preserva o espaço original no fluxo. absolute e fixed retiram o elemento do fluxo normal.", "h": "A posição parte do lugar original do elemento."}, {"q": "Para um botão permanecer no canto da janela enquanto a página rola, qual é a escolha usual?", "o": ["position: fixed", "color: fixed", "font-size: fixed"], "a": 0, "why": "position: fixed permite posicionar em relação à janela no caso usual. color e font-size não aceitam fixed para essa finalidade.", "h": "Precisamos controlar a posição, não a cor ou a fonte."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "web", "id": "web-funcoes", "group": "02 · Front-end", "title": "JavaScript: parâmetros e retorno", "time": 6, "source": "Moodle · Full Stack · aulas 01 a 06 liberadas; exercícios autorais de introdução", "body": "<p>Uma função reúne instruções. Parâmetros recebem os dados da chamada e return devolve o resultado.</p><pre><code>function soma(a, b) {\n  return a + b;\n}\nconst total = soma(4, 3);</code></pre><p>O evento de clique pode chamar uma função que lê campos, converte os valores e atualiza o resultado.</p><div class=\"example\">Valores de campos de texto são strings. Number(\"4\") produz o número 4.</div>", "qs": [{"q": "Quanto vale total?", "why": "A chamada fornece a=4 e b=3. return devolve 4 + 3 = 7, guardado em total.", "h": "Substitua os parâmetros pelos valores da chamada.", "o": ["7"], "a": 0}, {"q": "Por que converter os valores antes de uma soma numérica?", "o": ["Para evitar concatenar textos como \"4\" + \"3\" = \"43\"", "Porque HTML não aceita números na tela", "Porque toda função deve retornar texto"], "a": 0, "why": "O operador + pode concatenar strings. A conversão permite somar números e obter 7, em vez do texto \"43\".", "h": "O tipo de dado muda o comportamento do +."}], "sourceUrl": "https://moodle.fei.edu.br/course/section.php?id=3804"}, {"course": "dados", "id": "db-cardinalidade", "group": "02 · Cardinalidade e MER estendido", "title": "Cardinalidade: 1:N e N:N", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Cardinalidade indica quantas ocorrências podem se relacionar. Suponha: um cliente pode ter muitos pedidos, e cada pedido pertence a um único cliente.</p><p>Um aluno pode cursar várias disciplinas e uma disciplina pode ter vários alunos. Uma relação N:N costuma ser representada por uma tabela associativa no modelo relacional.</p>", "qs": [{"q": "Qual é a cardinalidade Cliente → Pedido?", "o": ["1:N", "1:1", "N:N"], "a": 0, "why": "Um cliente para muitos pedidos é 1:N. N:N exigiria que cada pedido também pudesse pertencer a vários clientes.", "h": "Leia os dois lados da regra."}, {"q": "Qual tabela pode ligar Aluno e Disciplina?", "o": ["Matricula(aluno_id, disciplina_id)", "Aluno(nome apenas)", "Disciplina(titulo apenas)"], "a": 0, "why": "Matricula guarda as referências às duas entidades e representa cada associação.", "h": "A tabela precisa identificar os dois lados da relação."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=24102"}, {"course": "dados", "id": "db-estendido", "group": "02 · Cardinalidade e MER estendido", "title": "Especialização e generalização", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Especialização divide uma entidade geral em tipos mais específicos. Por exemplo, Pessoa pode ter os subtipos Aluno e Professor. Os subtipos compartilham atributos da entidade geral.</p><p>Na especialização <strong>disjunta</strong>, uma ocorrência não pode pertencer simultaneamente a mais de um subtipo. Na sobreposta, isso pode acontecer, conforme as regras do domínio.</p>", "qs": [{"q": "Qual é o supertipo nesse exemplo?", "o": ["Pessoa", "Aluno", "Professor"], "a": 0, "why": "Pessoa é a entidade geral. Aluno e Professor são tipos específicos de Pessoa.", "h": "O supertipo é o conceito mais amplo."}, {"q": "Se uma pessoa pode ser Aluno e Professor ao mesmo tempo, a especialização é:", "o": ["Sobreposta", "Disjunta"], "a": 0, "why": "A participação simultânea em dois subtipos caracteriza sobreposição.", "h": "A regra permite acumular os dois papéis."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=24103"}, {"course": "dados", "id": "db-relacional", "group": "03 · Modelo Relacional", "title": "Tabelas, chaves e integridade", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Uma tabela guarda linhas (registros) e colunas (atributos). A chave primária identifica cada linha de forma única e não admite NULL.</p><p>Uma chave estrangeira referencia uma chave de outra tabela. Em Pedido(cliente_id), cliente_id pode apontar para Cliente(id).</p>", "qs": [{"q": "Qual é uma boa candidata a chave primária de Aluno?", "o": ["Um identificador único de matrícula", "O primeiro nome, que pode repetir", "A idade, que pode repetir"], "a": 0, "why": "A chave precisa distinguir cada aluno. Nome e idade podem se repetir.", "h": "Procure um identificador único."}, {"q": "Qual é a função de cliente_id em Pedido?", "o": ["Relacionar o pedido a um cliente existente", "Substituir todos os nomes dos clientes", "Guardar a quantidade de pedidos"], "a": 0, "why": "A referência liga cada pedido ao cliente correspondente e permite verificar integridade referencial.", "h": "O campo contém o identificador do cliente."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12805"}, {"course": "dados", "id": "db-algebra", "group": "04 · Álgebra Relacional", "title": "Álgebra relacional", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Na álgebra relacional, <strong>seleção</strong> filtra linhas por condição; <strong>projeção</strong> escolhe atributos (colunas).</p><div class=\"example\">Selecionar alunos com idade maior que 18 filtra registros. Projetar apenas nome escolhe uma coluna.</div><p>Uma junção combina registros de relações diferentes usando uma condição, como igualdade de chaves.</p>", "qs": [{"q": "Qual operação escolhe apenas as colunas nome e matrícula?", "o": ["Projeção", "Seleção", "Produto cartesiano"], "a": 0, "why": "Projeção escolhe atributos. Seleção determina quais linhas satisfazem uma condição.", "h": "Escolher colunas é diferente de filtrar linhas."}, {"q": "Qual condição liga Pedido ao Cliente correspondente?", "o": ["Pedido.cliente_id = Cliente.id", "Pedido.total = Cliente.nome", "Pedido.id = Pedido.total"], "a": 0, "why": "A chave estrangeira do pedido deve corresponder ao identificador do cliente.", "h": "Compare a referência com a chave referenciada."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12824"}, {"course": "dados", "id": "db-ddl", "group": "05 · SQL: DDL", "title": "DDL: criando estruturas", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>DDL define estruturas: CREATE TABLE cria uma tabela, ALTER TABLE altera a estrutura e DROP TABLE remove a tabela.</p><p>Uma definição simples de tabela pode declarar tipos e restrições.</p><pre><code>CREATE TABLE Aluno (\n  id INTEGER PRIMARY KEY,\n  nome VARCHAR(100) NOT NULL\n);</code></pre>", "qs": [{"q": "Qual comando cria uma tabela?", "o": ["CREATE TABLE", "INSERT INTO", "SELECT"], "a": 0, "why": "CREATE TABLE define a estrutura. INSERT insere linhas e SELECT consulta dados.", "h": "Criar estrutura pertence à DDL."}, {"q": "O que NOT NULL exige para nome?", "o": ["Que exista um valor não nulo", "Que o texto seja sempre único", "Que o texto contenha 100 caracteres exatos"], "a": 0, "why": "NOT NULL proíbe ausência de valor. Não exige unicidade nem comprimento exato.", "h": "NULL representa ausência de valor."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12809"}, {"course": "dados", "id": "db-dml", "group": "06 · SQL: DML — Parte 1", "title": "DML: inserindo e alterando dados", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>INSERT adiciona registros; UPDATE altera registros; DELETE remove registros. Esses comandos modificam os dados, não a estrutura da tabela.</p><pre><code>INSERT INTO Aluno (id, nome) VALUES (1, &#x27;Ana&#x27;);</code></pre><p>WHERE restringe quais linhas serão alteradas. Sem WHERE, um UPDATE pode afetar todas as linhas da tabela.</p>", "qs": [{"q": "O que esse comando faz?", "o": ["Insere a aluna Ana com id 1", "Cria uma nova tabela Aluno", "Remove a aluna Ana"], "a": 0, "why": "INSERT INTO adiciona uma linha à tabela existente. As colunas e os valores se correspondem pela ordem.", "h": "Observe o verbo INSERT."}, {"q": "Qual comando altera o nome apenas do aluno de id 1?", "o": ["UPDATE Aluno SET nome = 'Bia' WHERE id = 1;", "UPDATE Aluno SET nome = 'Bia';", "DELETE FROM Aluno WHERE id = 1;"], "a": 0, "why": "O WHERE id = 1 limita a alteração. A segunda opção altera todos os nomes, e DELETE remove registros.", "h": "Procure o filtro que identifica a linha."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32604"}, {"course": "dados", "id": "db-minmax", "group": "02 · Cardinalidade e MER estendido", "title": "Cardinalidade mínima e máxima", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Cardinalidade máxima responde quantas associações são permitidas. A mínima indica se a participação é obrigatória.</p><div class=\"example\">0..N: nenhuma ou várias associações.<br>1..N: pelo menos uma.<br>0..1: nenhuma ou uma.<br>1..1: exatamente uma.</div><p>Analise a regra nos dois sentidos. Suponha que cada pedido pertença obrigatoriamente a um único cliente.</p>", "qs": [{"q": "Um cliente pode existir sem pedidos e pode fazer vários. Qual faixa descreve a quantidade de pedidos por cliente?", "o": ["0..N", "1..1", "1..N"], "a": 0, "why": "A ausência de pedidos é permitida, então o mínimo é 0. Vários pedidos são permitidos, então o máximo é N.", "h": "Separe a pergunta do mínimo da pergunta do máximo."}, {"q": "Quantos clientes devem estar associados a cada pedido?", "o": ["1..1", "0..N", "0..1"], "a": 0, "why": "A associação é obrigatória e única: mínimo 1 e máximo 1. Isso não limita a quantidade de pedidos do cliente.", "h": "Leia a regra do ponto de vista de um pedido."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=24102"}, {"course": "dados", "id": "db-completude", "group": "02 · Cardinalidade e MER estendido", "title": "Herança e restrições de especialização", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Uma subclasse herda os atributos e relacionamentos da superclasse e pode ter características específicas.</p><div class=\"example\">Funcionário tem nome. Engenheiro é um subtipo e acrescenta tipo de engenharia.</div><p>Uma especialização é <strong>total</strong> quando toda ocorrência da superclasse pertence a pelo menos uma subclasse. É <strong>parcial</strong> quando alguma pode não pertencer a nenhuma.</p><p>Essa regra é independente de disjunção ou sobreposição.</p>", "qs": [{"q": "Onde o nome de Engenheiro é definido no modelo conceitual desse exemplo?", "o": ["Na superclasse Funcionário, sendo herdado", "Apenas em uma entidade sem relação com Funcionário", "Não pode existir em Engenheiro"], "a": 0, "why": "Engenheiro herda o atributo nome de Funcionário. O subtipo acrescenta seus atributos específicos.", "h": "O que é comum aos tipos fica na superclasse."}, {"q": "Se todo Serviço é obrigatoriamente Banho, Tosa ou Consulta, a especialização é:", "o": ["Total", "Parcial", "Sempre sobreposta"], "a": 0, "why": "Toda ocorrência foi coberta pelos subtipos: a especialização é total. A regra não diz, sozinha, se é permitido pertencer a mais de um subtipo.", "h": "Completude trata de cobrir todas as ocorrências."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=24103"}, {"course": "dados", "id": "db-map-1n", "group": "03 · Modelo Relacional", "title": "Mapeando uma relação 1:N", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Em uma relação 1:N, uma implementação usual coloca a chave estrangeira na tabela do lado N.</p><div class=\"example\">Um Departamento possui vários Funcionários. Cada Funcionário pertence a um Departamento.</div><p>Se todo funcionário precisa de departamento, a FK pode ser NOT NULL. A chave estrangeira verifica a referência; NOT NULL exige que ela esteja preenchida.</p>", "qs": [{"q": "Onde guardar departamento_id nessa implementação?", "o": ["Na tabela Funcionário", "Uma lista de funcionários dentro do nome do departamento", "Em uma coluna de cor"], "a": 0, "why": "Cada funcionário precisa apontar para um departamento. A FK fica no lado N e referencia a chave do departamento.", "h": "O lado N guarda a referência ao lado 1."}, {"q": "Qual combinação expressa referência válida e preenchimento obrigatório?", "o": ["FOREIGN KEY e NOT NULL", "Apenas um texto chamado departamento", "Apenas DEFAULT 0"], "a": 0, "why": "São duas regras diferentes: a FK garante a referência válida e NOT NULL proíbe ausência de valor.", "h": "Identifique a regra de vínculo e a regra de obrigatoriedade."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12805"}, {"course": "dados", "id": "db-map-mn", "group": "03 · Modelo Relacional", "title": "Mapeando uma relação N:N", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Uma relação N:N costuma virar uma tabela associativa com referências para os dois lados. A combinação dessas referências pode formar a chave primária.</p><div class=\"example\">Aluno cursa Disciplina → Matricula(aluno_id, disciplina_id).</div><p>Um atributo do relacionamento vai para a tabela que representa a associação.</p><div class=\"example\">A nota pertence à matrícula do aluno em uma disciplina.</div>", "qs": [{"q": "Qual estrutura representa a associação?", "o": ["Matricula com aluno_id e disciplina_id", "Uma coluna única no nome do aluno com todas as disciplinas", "Apenas remover Disciplina"], "a": 0, "why": "A associativa guarda cada vínculo entre um aluno e uma disciplina. Uma lista em um único campo dificulta representar os registros relacionais.", "h": "Precisamos identificar os dois participantes de cada vínculo."}, {"q": "Onde guardar a nota nesse modelo?", "o": ["Na tabela Matricula", "Somente em Aluno, uma nota para todas as disciplinas", "Somente em Disciplina, uma nota igual para todos"], "a": 0, "why": "A nota depende do par aluno–disciplina. Por isso é atributo da associação e fica em Matricula.", "h": "Pergunte de quais participantes o valor depende."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12805"}, {"course": "dados", "id": "db-map-multivalorado", "group": "03 · Modelo Relacional", "title": "Mapeando atributos multivalorados", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Um atributo multivalorado pode virar uma tabela própria com o identificador da entidade e um valor por linha.</p><div class=\"example\">Cliente(id, nome)<br>Telefone(cliente_id, numero)</div><p>A chave pode combinar o identificador da entidade e o valor do atributo, quando essa combinação satisfizer as regras do domínio.</p>", "qs": [{"q": "Como representar dois telefones do mesmo cliente?", "o": ["Duas linhas em Telefone com o mesmo cliente_id", "Dois clientes fictícios", "Apagar o segundo telefone"], "a": 0, "why": "A referência ao cliente se repete, mas cada linha guarda um telefone. Não precisamos duplicar o cadastro do cliente.", "h": "Uma linha representa um valor do atributo."}, {"q": "Qual chave evita registrar duas vezes o mesmo telefone para o mesmo cliente?", "o": ["(cliente_id, numero)", "Apenas cliente_id, permitindo só um telefone", "Apenas a quantidade de caracteres"], "a": 0, "why": "cliente_id sozinho impediria vários telefones. A combinação distingue os valores de cada cliente.", "h": "Uma entidade pode ter mais de um valor, mas o mesmo par não precisa se repetir."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12805"}, {"course": "dados", "id": "db-map-heranca", "group": "03 · Modelo Relacional", "title": "Mapeando superclasses e subclasses", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Uma estratégia cria uma tabela para a superclasse e uma para cada subclasse. A chave da subclasse também referencia a superclasse.</p><div class=\"example\">Funcionario(id, nome)<br>Engenheiro(id, tipo)<br>Engenheiro.id → Funcionario.id</div><p>Há outras estratégias: uma tabela com discriminador para subtipos disjuntos, ou indicadores booleanos para sobreposição. Usar apenas tabelas das subclasses exige especialização total para não perder ocorrências da superclasse.</p>", "qs": [{"q": "Qual papel id exerce em Engenheiro nessa estratégia?", "o": ["Chave primária e chave estrangeira", "Somente um texto livre", "Um atributo que não precisa corresponder a Funcionário"], "a": 0, "why": "id identifica o engenheiro e o liga ao funcionário correspondente. A mesma coluna pode ser PK e FK.", "h": "O subtipo também é uma ocorrência do supertipo."}, {"q": "Por que apenas tabelas de subclasses pode falhar em uma especialização parcial?", "o": ["Ocorrências sem subtipo ficariam sem lugar para ser guardadas", "Porque toda chave estrangeira é proibida", "Porque subtipos não possuem atributos"], "a": 0, "why": "Na especialização parcial, uma ocorrência da superclasse pode não pertencer a nenhuma subclasse. Sem tabela da superclasse, ela poderia não ser representada.", "h": "Pense em uma ocorrência que não entra em nenhum subtipo."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32432"}, {"course": "dados", "id": "db-produto", "group": "04 · Álgebra Relacional", "title": "Produto cartesiano", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>O produto cartesiano combina cada linha de uma relação com cada linha da outra. Com m e n linhas, o resultado tem m × n linhas.</p><p>O produto sozinho pode criar combinações que não representam vínculos reais. Para relacionar Pedido a Cliente, selecione os pares cujos identificadores correspondem.</p>", "qs": [{"q": "Uma relação tem 3 linhas e a outra tem 2. Quantas combinações o produto gera?", "why": "Cada uma das 3 linhas combina com as 2 da outra relação: 3 × 2 = 6.", "h": "Multiplique as quantidades de linhas.", "o": ["6"], "a": 0}, {"q": "Qual condição mantém os pares corretos?", "o": ["Pedido.cliente_id = Cliente.id", "Pedido.total = Cliente.nome", "Não aplicar condição alguma"], "a": 0, "why": "O vínculo é dado pela referência ao identificador do cliente. Sem a condição, todos os pares permanecem.", "h": "Compare a chave estrangeira com a chave referenciada."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12824"}, {"course": "dados", "id": "db-uniao", "group": "04 · Álgebra Relacional", "title": "União e compatibilidade", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>A união reúne as tuplas de duas relações compatíveis e elimina duplicatas na álgebra relacional clássica. É preciso ter o mesmo número de atributos e domínios compatíveis nas posições correspondentes.</p><p>Pense em relações como conjuntos, sem duplicatas.</p><div class=\"example\">A = {1, 2}<br>B = {2, 3}</div>", "qs": [{"q": "O que precisamos verificar antes de unir duas relações?", "o": ["Quantidade de atributos e domínios por posição", "A cor do cabeçalho", "Somente se os nomes das tabelas começam com a mesma letra"], "a": 0, "why": "A compatibilidade depende da estrutura das relações, não da aparência ou do nome das tabelas.", "h": "Compare as colunas correspondentes."}, {"q": "Quantos valores distintos existem em A ∪ B?", "why": "A união contém {1, 2, 3}. O 2 aparece apenas uma vez no conjunto resultante.", "h": "Reúna os valores e retire repetições.", "o": ["3"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32452"}, {"course": "dados", "id": "db-diferenca", "group": "04 · Álgebra Relacional", "title": "Diferença e interseção", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>A − B mantém as tuplas que estão em A e não estão em B. A ordem importa.</p><div class=\"example\">A = {1, 2, 3}<br>B = {2, 3, 4}</div><p>A ∩ B mantém apenas as tuplas presentes nas duas relações.</p><div class=\"example\">A = {1, 2, 3}<br>B = {2, 3, 4}</div>", "qs": [{"q": "Qual é o resultado de A − B?", "o": ["{1}", "{4}", "{2, 3}"], "a": 0, "why": "1 está em A e não está em B. {4} seria B − A, e {2, 3} seria a interseção.", "h": "Comece com A e retire os elementos que também estão em B."}, {"q": "Qual é o resultado de A ∩ B?", "o": ["{2, 3}", "{1, 4}", "{1, 2, 3, 4}"], "a": 0, "why": "2 e 3 pertencem aos dois conjuntos. Reunir todos os valores faria a união.", "h": "Procure a parte em comum."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32452"}, {"course": "dados", "id": "db-juncao-renomear", "group": "04 · Álgebra Relacional", "title": "Junção natural e renomeação", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>A junção natural combina linhas com valores iguais nos atributos de mesmo nome e apresenta uma única cópia desses atributos comuns.</p><div class=\"example\">Se as relações compartilham apenas cliente_id, esse atributo define a correspondência.</div><p>Renomear uma relação permite distinguir duas ocorrências dela na mesma consulta.</p><div class=\"example\">Para comparar funcionários entre si, podemos usar F1 e F2 como nomes diferentes da relação Funcionario.</div>", "qs": [{"q": "O que acontece se existirem dois atributos de mesmo nome nas relações?", "o": ["A junção natural exige igualdade nos dois", "Apenas um deles é considerado, sempre", "Os nomes são ignorados"], "a": 0, "why": "A junção natural usa todos os atributos de mesmo nome. É necessário conferir os esquemas para não impor condições indesejadas.", "h": "Todos os nomes comuns participam da correspondência."}, {"q": "Por que renomear nesse caso?", "o": ["Para distinguir os dois papéis na consulta", "Para apagar as linhas originais", "Para mudar a idade dos funcionários"], "a": 0, "why": "A renomeação resolve a ambiguidade entre os dois papéis. Ela não altera os valores dos registros.", "h": "A consulta precisa saber a qual ocorrência cada atributo pertence."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32452"}, {"course": "dados", "id": "db-divisao", "group": "04 · Álgebra Relacional", "title": "Divisão e resultados intermediários", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>A divisão relacional aparece em perguntas com <strong>“todos”</strong>.</p><div class=\"example\">AlunoDisciplina contém (Ana, BD), (Ana, Web) e (Bia, BD). Disciplinas exigidas = {BD, Web}.</div><p>Uma atribuição armazena o resultado de uma operação em uma relação temporária para reutilização.</p><div class=\"example\">T ← seleção de alunos ativos.</div>", "qs": [{"q": "Quem está associado a todas as disciplinas exigidas?", "o": ["Ana", "Bia", "As duas"], "a": 0, "why": "Ana tem BD e Web. Bia tem apenas BD, então não satisfaz a condição para todas as disciplinas.", "h": "Confira cada disciplina exigida, para cada aluna."}, {"q": "Qual é a finalidade de T nesse exemplo?", "o": ["Reutilizar o resultado em outra operação", "Alterar automaticamente todos os alunos no banco", "Eliminar a condição da consulta"], "a": 0, "why": "T guarda o resultado intermediário. A atribuição da álgebra não equivale a um UPDATE nos dados originais.", "h": "Pense em um resultado temporário."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32452"}, {"course": "dados", "id": "db-tipos", "group": "05 · SQL: DDL", "title": "Tipos de dados e schemas", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Escolha o tipo conforme o dado: INTEGER para contagens, VARCHAR para texto com limite, DATE para datas e NUMERIC(p,s) para decimais com precisão e escala definidas.</p><p>Um schema organiza objetos dentro do banco. O nome schema.tabela identifica a tabela nesse espaço.</p><div class=\"example\">CREATE SCHEMA estudos;<br>CREATE TABLE estudos.aluno (...);</div>", "qs": [{"q": "Para guardar um preço com duas casas decimais de forma exata, qual opção é adequada?", "o": ["NUMERIC(10,2)", "Uma aproximação em ponto flutuante é sempre exata", "DATE"], "a": 0, "why": "NUMERIC(10,2) é um tipo decimal exato com escala 2. Ponto flutuante pode introduzir aproximações, e DATE guarda datas.", "h": "Para valores monetários, considere a precisão decimal."}, {"q": "Em estudos.aluno, o que é estudos?", "o": ["O schema", "Uma linha da tabela", "Um valor de idade"], "a": 0, "why": "estudos identifica o schema que contém a tabela aluno.", "h": "O prefixo organiza o objeto dentro do banco."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12809"}, {"course": "dados", "id": "db-restricoes", "group": "05 · SQL: DDL", "title": "CHECK, DEFAULT e UNIQUE", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>CHECK impõe uma condição aos valores; DEFAULT fornece um valor quando a coluna é omitida na inserção; UNIQUE impõe unicidade.</p><pre><code>quantidade INTEGER DEFAULT 0 CHECK (quantidade &gt;= 0)</code></pre><p>DEFAULT é aplicado quando usamos o padrão ou omitimos a coluna. Ele não substitui automaticamente um NULL explícito.</p><pre><code>status VARCHAR(20) DEFAULT &#x27;Pendente&#x27;</code></pre>", "qs": [{"q": "Qual valor é rejeitado por esse CHECK?", "o": ["-1", "0", "5"], "a": 0, "why": "A condição exige quantidade maior ou igual a zero. DEFAULT não transforma automaticamente um valor negativo em zero.", "h": "Avalie a condição para cada valor."}, {"q": "Se status for omitido no INSERT, qual será o valor padrão?", "o": ["Pendente", "NULL obrigatoriamente", "O nome da tabela"], "a": 0, "why": "A definição estabelece Pendente como padrão para a coluna omitida.", "h": "Leia o valor indicado após DEFAULT."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12809"}, {"course": "dados", "id": "db-alter-drop", "group": "05 · SQL: DDL", "title": "ALTER, DROP e referências", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>CREATE TABLE cria a estrutura. ALTER TABLE modifica a estrutura existente. DROP TABLE remove a tabela.</p><p>Uma FOREIGN KEY liga uma coluna a uma chave referenciada. Ao criar tabelas com essa dependência, a tabela referenciada normalmente precisa existir primeiro.</p>", "qs": [{"q": "Qual comando adiciona uma coluna email a aluno?", "o": ["ALTER TABLE aluno ADD COLUMN email VARCHAR(100);", "UPDATE aluno SET email = 1;", "DELETE FROM aluno;"], "a": 0, "why": "ADD COLUMN em ALTER TABLE modifica o esquema. UPDATE altera dados e DELETE remove linhas.", "h": "Precisamos alterar a estrutura, não os registros."}, {"q": "Se pedido.cliente_id referencia cliente.id, qual tabela criar primeiro no caso usual?", "o": ["cliente", "pedido", "A ordem nunca importa"], "a": 0, "why": "A tabela cliente fornece o alvo da referência. Depois criamos pedido com a FK.", "h": "Crie o objeto referenciado antes da referência."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=12809"}, {"course": "dados", "id": "db-insert-fk", "group": "06 · SQL: DML — Parte 1", "title": "INSERT e integridade referencial", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>Uma FK preenchida precisa corresponder a um valor existente na chave referenciada, salvo regras específicas de adiamento da verificação. Neste exercício, a verificação é imediata.</p><div class=\"example\">Cliente tem apenas id=1. Pedido.cliente_id referencia Cliente.id.</div><p>No caso usual com verificação imediata, insira primeiro o registro pai e depois o filho que o referencia.</p>", "qs": [{"q": "O que ocorre ao inserir um pedido com cliente_id=99?", "o": ["Erro de chave estrangeira", "O cliente 99 é criado automaticamente", "O vínculo é ignorado"], "a": 0, "why": "Não existe cliente 99 para satisfazer a referência. Uma FK não cria o registro pai automaticamente.", "h": "Verifique se o identificador existe na tabela referenciada."}, {"q": "Qual ordem permite cadastrar um novo cliente e seu pedido?", "o": ["Inserir Cliente → inserir Pedido", "Inserir Pedido com referência inexistente → inserir Cliente", "Apenas inserir Pedido"], "a": 0, "why": "O cliente precisa existir quando o pedido for verificado.", "h": "A referência deve apontar para algo existente."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32604"}, {"course": "dados", "id": "db-delete", "group": "06 · SQL: DML — Parte 1", "title": "DELETE e o efeito do WHERE", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>DELETE remove linhas. WHERE determina quais serão removidas. Sem WHERE, o comando solicita a remoção de todas as linhas da tabela.</p><p>Uma exclusão pode ser impedida por referências de outras tabelas. Considere uma FK com comportamento padrão e pedidos que ainda apontam para um cliente.</p>", "qs": [{"q": "Qual comando remove somente o pedido de id 3?", "o": ["DELETE FROM pedido WHERE id = 3;", "DELETE FROM pedido;", "DROP TABLE pedido;"], "a": 0, "why": "O filtro identifica a linha. DELETE sem filtro solicita todas as linhas; DROP remove a estrutura da tabela.", "h": "Procure a condição que identifica o registro."}, {"q": "Por que a exclusão desse cliente pode ser bloqueada?", "o": ["Para não deixar pedidos com referência inexistente", "Porque DELETE nunca é permitido", "Porque o nome da tabela tem poucas letras"], "a": 0, "why": "A integridade referencial protege os vínculos. O efeito exato depende da ação definida na FK.", "h": "Os registros filhos ainda dependem do pai."}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32604"}, {"course": "dados", "id": "db-select", "group": "06 · SQL: DML — Parte 1", "title": "SELECT para conferir resultados", "time": 6, "source": "Banco de Dados · apresentação do bloco lida online; explicações e exercícios autorais", "body": "<p>SELECT escolhe colunas, FROM informa a tabela e WHERE filtra linhas. A consulta permite conferir os resultados depois de INSERT, UPDATE ou DELETE.</p><p>Considere a tabela abaixo:</p><table><tr><th>id</th><th>idade</th></tr><tr><td>1</td><td>17</td></tr><tr><td>2</td><td>20</td></tr><tr><td>3</td><td>22</td></tr></table><div class=\"example\">SELECT * FROM aluno WHERE idade >= 20;</div>", "qs": [{"q": "Qual consulta mostra nome apenas do aluno de id 2?", "o": ["SELECT nome FROM aluno WHERE id = 2;", "UPDATE aluno SET nome = 2;", "SELECT id FROM aluno;"], "a": 0, "why": "A primeira opção escolhe nome e aplica o filtro id=2. UPDATE altera dados e a última consulta escolhe outra coluna sem filtro.", "h": "Separe coluna desejada, tabela e condição."}, {"q": "Quantas linhas essa consulta retorna?", "why": "As idades 20 e 22 satisfazem >= 20. A linha com idade 17 fica de fora.", "h": "O limite 20 também entra no resultado.", "o": ["2"], "a": 0}], "sourceUrl": "https://moodle.fei.edu.br/mod/url/view.php?id=32604"}]);
Object.assign(STEPS,{"fracoes": [{"intro": "<p>À direita da vírgula, os valores das posições são <strong>1/2, 1/4, 1/8…</strong> Cada passo divide o valor por 2.</p><div class=\"example\">0,11₂ = 1/2 + 1/4 = 0,75₁₀.</div>", "answer": "0.625", "kind": "fraction", "label": "Resultado em decimal (vírgula ou ponto)", "error": "Some 1/2 + 0/4 + 1/8 = 0,5 + 0,125 = 0,625. A terceira casa fracionária vale 1/8, não 1/3."}, {"intro": "<p>Para converter uma fração decimal em binário, multiplique a fração por 2. Anote a parte inteira e repita com a nova parte fracionária.</p><div class=\"example\">0,25 × 2 = 0,5 → bit 0.<br>0,5 × 2 = 1,0 → bit 1.<br>Resultado: 0,01₂. Os bits são lidos na ordem em que aparecem.</div>", "errors": ["", "0,75 × 2 = 1,5 (bit 1). Depois, 0,5 × 2 = 1,0 (bit 1). Resultado 0,11₂. Não inverta a ordem dos bits fracionários.", "0,75 × 2 = 1,5 (bit 1). Depois, 0,5 × 2 = 1,0 (bit 1). Resultado 0,11₂. Não inverta a ordem dos bits fracionários."]}], "tabela-expressao": [{"intro": "<p>Para obter uma expressão a partir da tabela, observe as linhas em que a saída é 1. Cada linha vira um termo AND. Uma entrada 0 entra negada; uma entrada 1 entra sem negação. Una os termos com OR.</p><div class=\"example\">Se apenas A=0, B=1 produz saída 1, o termo é ¬A · B.</div>", "errors": ["", "A deve valer 1, então aparece sem negação. B deve valer 0, então aparece como ¬B. Junte as condições por AND: A · ¬B.", "A deve valer 1, então aparece sem negação. B deve valer 0, então aparece como ¬B. Junte as condições por AND: A · ¬B."]}, {"intro": "<p>Quando várias linhas produzem 1, use a soma dos produtos. Para A,B = 01 e 11, obtemos ¬A·B + A·B. Os dois termos compartilham B.</p>", "errors": ["Nas duas linhas, B é sempre 1 e A pode variar. A saída depende somente de B.", "", "Nas duas linhas, B é sempre 1 e A pode variar. A saída depende somente de B."]}], "alg-sequencia": [{"intro": "<p>Um algoritmo é uma sequência de passos para resolver um problema. <strong>Entrada</strong> é o que recebemos; <strong>processamento</strong> é o que fazemos; <strong>saída</strong> é o resultado.</p><div class=\"example\">Receber dois preços → somar → mostrar o total.</div>", "errors": ["", "Os preços entram no cálculo. A soma é o processamento e o total é a saída.", "Os preços entram no cálculo. A soma é o processamento e o total é a saída."]}, {"intro": "<p>Em lógica sequencial, cada instrução usa o estado produzido pelas anteriores.</p><pre><code>x = 3\nx = x + 2\nprint(x)</code></pre>", "answer": "5", "kind": "decimal", "label": "Sua resposta", "error": "x começa com 3. A instrução seguinte guarda 3 + 2 em x. print mostra o valor atual, 5."}], "alg-variaveis": [{"intro": "<p>Uma variável tem um nome e guarda um valor. Em Python, = atribui e == compara. Multiplicação tem precedência sobre adição.</p><pre><code>total = 2 + 3 * 4</code></pre>", "answer": "14", "kind": "decimal", "label": "Sua resposta", "error": "Primeiro 3 * 4 = 12. Depois 2 + 12 = 14. Para somar 2 + 3 primeiro, seriam necessários parênteses."}, {"intro": "<p>input() lê texto. Para usar uma idade em uma conta, converta o texto para um número com int().</p><pre><code>idade = int(input(&quot;Idade: &quot;))</code></pre>", "errors": ["", "input() retorna texto. int() tenta transformar esse texto em um número inteiro. Um texto como \"abc\" não pode ser convertido dessa forma.", "input() retorna texto. int() tenta transformar esse texto em um número inteiro. Um texto como \"abc\" não pode ser convertido dessa forma."]}], "alg-condicoes": [{"intro": "<p>if executa um bloco quando a condição é verdadeira; else executa a alternativa. A indentação mostra quais instruções pertencem ao bloco.</p><pre><code>nota = 7\nif nota &gt;= 6:\n    print(&quot;Aprovada&quot;)\nelse:\n    print(&quot;Revisar&quot;)</code></pre>", "errors": ["", "7 >= 6 é verdadeiro. Apenas o bloco do if é executado. O else é a alternativa, não uma etapa adicional.", "7 >= 6 é verdadeiro. Apenas o bloco do if é executado. O else é a alternativa, não uma etapa adicional."]}, {"intro": "<p>Os operadores &gt;, &lt;, &gt;=, &lt;=, == e != comparam valores. == testa igualdade; = atribui.</p>", "errors": ["", "x == 10 compara. x = 10 atribui o valor 10. x != 10 testa se são diferentes.", "x == 10 compara. x = 10 atribui o valor 10. x != 10 testa se são diferentes."]}], "alg-logicos": [{"intro": "<p>Em condições booleanas de Python: and exige as duas condições verdadeiras; or aceita pelo menos uma; not inverte o resultado.</p><pre><code>idade = 20\ntem_documento = False\npode_entrar = idade &gt;= 18 and tem_documento</code></pre>", "errors": ["", "A idade satisfaz a condição, mas tem_documento é False. and exige que as duas condições sejam verdadeiras."]}, {"intro": "<p>Use parênteses para deixar claras as combinações de condições.</p><pre><code>(5 &gt; 3) or (2 &gt; 8)</code></pre>", "errors": ["", "5 > 3 é True. Em or, uma condição verdadeira já torna o resultado True."]}], "alg-repeticao": [{"intro": "<p>for percorre os itens de uma sequência. range(4) produz os inteiros 0, 1, 2 e 3: o limite final não entra.</p><pre><code>for i in range(4):\n    print(i)</code></pre>", "answer": "4", "kind": "decimal", "label": "Sua resposta", "error": "range(4) tem quatro valores: 0, 1, 2 e 3. Começar em zero não acrescenta uma quinta repetição."}, {"intro": "<p>while repete enquanto a condição for verdadeira. Atualize a variável usada na condição para permitir o término.</p><pre><code>x = 0\nwhile x &lt; 3:\n    x = x + 1\nprint(x)</code></pre>", "answer": "3", "kind": "decimal", "label": "Sua resposta", "error": "x passa por 1, 2 e 3. Quando chega a 3, x < 3 é falso e o laço termina. print está fora do laço."}], "alg-aninhados": [{"intro": "<p>Um laço dentro de outro roda completamente para cada repetição externa.</p><pre><code>for linha in range(2):\n    for coluna in range(3):\n        print(&quot;*&quot;)</code></pre>", "answer": "6", "kind": "decimal", "label": "Sua resposta", "error": "O laço interno roda 3 vezes para cada uma das 2 repetições externas. Total: 2 × 3 = 6."}, {"intro": "<p>Um acumulador guarda um resultado que cresce a cada repetição. Inicialize antes do laço.</p><pre><code>soma = 0\nfor n in [1, 2, 3]:\n    soma = soma + n\nprint(soma)</code></pre>", "answer": "6", "kind": "decimal", "label": "Sua resposta", "error": "soma vai de 0 para 1, depois para 3 e finalmente para 6. A variável não é reiniciada dentro do laço."}], "alg-funcoes": [{"intro": "<p>Uma função reúne instruções reutilizáveis. Parâmetros recebem dados; return entrega um resultado a quem chamou.</p><pre><code>def dobro(n):\n    return n * 2\n\nprint(dobro(4))</code></pre>", "answer": "8", "kind": "decimal", "label": "Sua resposta", "error": "A chamada dobro(4) usa n=4. return devolve 4 * 2 = 8."}, {"intro": "<p>print mostra algo na tela. return fornece um valor ao restante do programa. Uma função sem return explícito retorna None.</p>", "errors": ["", "return entrega o valor à expressão que chamou a função. print apenas escreve na saída e não substitui esse retorno.", "return entrega o valor à expressão que chamou a função. print apenas escreve na saída e não substitui esse retorno."]}], "alg-listas-tuplas": [{"intro": "<p>Listas armazenam vários itens em ordem. O primeiro índice é <strong>0</strong>.</p><pre><code>notas = [7, 8, 9]\nprint(notas[1])</code></pre>", "answer": "8", "kind": "decimal", "label": "Sua resposta", "error": "O índice 0 contém 7; o índice 1 contém 8. Não confunda índice com posição contada a partir de 1."}, {"intro": "<p>Uma lista pode ter itens substituídos, adicionados ou removidos. Uma tupla não permite substituir seus itens depois de criada.</p><pre><code>lista = [1, 2]\ntupla = (1, 2)</code></pre>", "errors": ["", "Listas são mutáveis. Tuplas não permitem atribuição a posições como tupla[0] = 9."]}], "alg-listas": [{"intro": "<p>append adiciona um item ao final. len informa a quantidade de itens.</p><pre><code>itens = [2, 4]\nitens.append(6)\nprint(len(itens))</code></pre>", "answer": "3", "kind": "decimal", "label": "Sua resposta", "error": "A lista passa a ser [2, 4, 6], com três itens. len conta itens, não soma seus valores."}, {"intro": "<p>Ao percorrer uma lista, a variável do laço recebe cada item em ordem.</p><pre><code>total = 0\nfor valor in [2, 4, 6]:\n    total += valor\nprint(total)</code></pre>", "answer": "12", "kind": "decimal", "label": "Sua resposta", "error": "total acumula 2 + 4 + 6 = 12. += soma ao valor atual e guarda o resultado."}], "alg-matrizes": [{"intro": "<p>Uma matriz pode ser uma lista de linhas. Use matriz[linha][coluna], com índices começando em zero.</p><pre><code>m = [[1, 2], [3, 4]]\nprint(m[1][0])</code></pre>", "answer": "3", "kind": "decimal", "label": "Sua resposta", "error": "m[1] seleciona a segunda linha, [3, 4]. O índice [0] seleciona seu primeiro item, 3."}, {"intro": "<p>Uma matriz com 3 linhas e 4 colunas tem 3 × 4 posições. Dois laços ajudam a visitar todas elas.</p>", "answer": "10", "kind": "decimal", "label": "Sua resposta", "error": "São cinco posições em cada uma das duas linhas: 2 × 5 = 10."}], "alg-dicionarios": [{"intro": "<p>Dicionários associam chaves a valores. Em vez de buscar por posição, usamos uma chave.</p><pre><code>aluna = {&quot;nome&quot;: &quot;Ana&quot;, &quot;idade&quot;: 19}\nprint(aluna[&quot;idade&quot;])</code></pre>", "answer": "19", "kind": "decimal", "label": "Sua resposta", "error": "A chave \"idade\" está associada ao valor 19. O nome da chave não é o valor armazenado."}, {"intro": "<p>get permite buscar uma chave e fornecer um valor padrão quando ela não existir.</p><pre><code>dados = {&quot;nome&quot;: &quot;Ana&quot;}\nprint(dados.get(&quot;curso&quot;, &quot;Não informado&quot;))</code></pre>", "errors": ["", "A chave \"curso\" não existe. get devolve o valor padrão \"Não informado\".", "A chave \"curso\" não existe. get devolve o valor padrão \"Não informado\"."]}], "alg-arquivos": [{"intro": "<p>open abre um arquivo. O modo \"r\" lê; \"w\" escreve substituindo o conteúdo; \"a\" acrescenta ao final. with ajuda a fechar o arquivo ao sair do bloco.</p>", "errors": ["", "O modo a significa append: acrescentar. w pode apagar o conteúdo anterior; r é para leitura.", "O modo a significa append: acrescentar. w pode apagar o conteúdo anterior; r é para leitura."]}, {"intro": "<p>read lê o conteúdo do arquivo. Aqui o arquivo é aberto apenas para leitura.</p><pre><code>with open(&quot;notas.txt&quot;, &quot;r&quot;, encoding=&quot;utf-8&quot;) as arquivo:\n    texto = arquivo.read()</code></pre>", "errors": ["", "read() retorna o conteúdo, que é atribuído a texto. A leitura não cria uma pasta nem altera o nome do arquivo.", "read() retorna o conteúdo, que é atribuído a texto. A leitura não cria uma pasta nem altera o nome do arquivo."]}], "alg-strings-modulos": [{"intro": "<p>Strings são sequências de caracteres. Também usam índices a partir de zero. len conta seus caracteres.</p><pre><code>texto = &quot;FEI&quot;\nprint(len(texto))</code></pre>", "answer": "3", "kind": "decimal", "label": "Sua resposta", "error": "A string contém F, E e I: três caracteres."}, {"intro": "<p>Um módulo organiza funções reutilizáveis. import permite usar esse código.</p><pre><code>import math\nprint(math.sqrt(16))</code></pre>", "answer": "4", "kind": "decimal", "label": "Sua resposta", "error": "sqrt calcula a raiz quadrada. A raiz de 16 é 4. Python mostra 4.0, que é numericamente igual a 4."}, {"intro": "<p>Em uma interface gráfica, eventos como cliques disparam funções associadas aos controles.</p>", "errors": ["", "Um botão normalmente aciona uma função ligada ao evento de clique. Essa função lê entradas, calcula e atualiza a interface.", "Um botão normalmente aciona uma função ligada ao evento de clique. Essa função lê entradas, calcula e atualiza a interface."]}], "db-entidades": [{"intro": "<p>Uma entidade representa algo sobre o qual guardamos dados. Atributos descrevem essa entidade. Relacionamentos ligam entidades.</p><div class=\"example\">Aluno tem nome e matrícula. Aluno realiza matrícula em Disciplina.</div>", "errors": ["", "nome descreve Aluno. Disciplina é outra entidade; cursa descreve uma relação.", "nome descreve Aluno. Disciplina é outra entidade; cursa descreve uma relação."]}, {"intro": "<p>Um modelo evita misturar conceitos diferentes. Clientes e pedidos são entidades ligadas por um relacionamento.</p>", "errors": ["", "Cliente faz Pedido liga duas entidades. As outras frases descrevem atributos.", "Cliente faz Pedido liga duas entidades. As outras frases descrevem atributos."]}], "web-html": [{"intro": "<p>HTML organiza e dá significado ao conteúdo. Elementos usam tags como &lt;h1&gt; para título principal e &lt;p&gt; para parágrafo.</p><pre><code>&lt;h1&gt;Minha página&lt;/h1&gt;\n&lt;p&gt;Bem-vinda!&lt;/p&gt;</code></pre>", "errors": ["", "p identifica um parágrafo. h1 identifica um título e img insere uma imagem.", "p identifica um parágrafo. h1 identifica um título e img insere uma imagem."]}, {"intro": "<p>Links usam o elemento a e o atributo href para definir o destino.</p><pre><code>&lt;a href=&quot;https://exemplo.com&quot;&gt;Visitar&lt;/a&gt;</code></pre>", "errors": ["", "href indica o destino. class identifica classes de estilo; alt é texto alternativo em imagens.", "href indica o destino. class identifica classes de estilo; alt é texto alternativo em imagens."]}], "web-css": [{"intro": "<p>CSS controla a apresentação. Um seletor escolhe elementos, e declarações definem propriedades.</p><pre><code>.destaque {\n  color: green;\n}</code></pre>", "errors": ["", "O ponto antes do nome seleciona uma classe. Para id, usamos #.", "O ponto antes do nome seleciona uma classe. Para id, usamos #."]}, {"intro": "<p>color altera a cor do texto. background-color altera o fundo. padding é espaço interno; margin é espaço externo.</p>", "errors": ["", "padding fica entre o conteúdo e a borda. margin fica do lado de fora da borda.", "padding fica entre o conteúdo e a borda. margin fica do lado de fora da borda."]}], "web-layout": [{"intro": "<p>Flexbox distribui elementos em uma dimensão, como uma linha ou coluna. Grid organiza linhas e colunas.</p><pre><code>.linha { display: flex; gap: 12px; }</code></pre>", "errors": ["", "gap define o espaçamento entre os itens do layout.", "gap define o espaçamento entre os itens do layout."]}, {"intro": "<p>Media queries aplicam regras sob condições, como largura máxima da tela. Isso ajuda a adaptar a interface ao celular.</p><pre><code>@media (max-width: 600px) {\n  .colunas { grid-template-columns: 1fr; }\n}</code></pre>", "errors": ["", "max-width estabelece um limite máximo inclusivo. A regra vale em 600px ou menos.", "max-width estabelece um limite máximo inclusivo. A regra vale em 600px ou menos."]}], "web-js": [{"intro": "<p>JavaScript adiciona comportamento à página. let declara uma variável que pode receber outro valor.</p><pre><code>let pontos = 2;\npontos = pontos + 3;</code></pre>", "answer": "5", "kind": "decimal", "label": "Sua resposta", "error": "A segunda atribuição usa 2 + 3 e guarda 5. A variável não mantém simultaneamente os dois valores."}, {"intro": "<p>=== compara valor e tipo sem converter automaticamente. Uma string como \"5\" e o número 5 têm tipos diferentes.</p><pre><code>5 === &quot;5&quot;</code></pre>", "errors": ["", "O número 5 e o texto \"5\" têm tipos diferentes, portanto a igualdade estrita é false."]}], "web-dom": [{"intro": "<p>O DOM representa os elementos da página para o JavaScript. Uma função pode localizar um elemento e atualizar seu texto.</p><pre><code>const titulo = document.getElementById(&quot;titulo&quot;);\ntitulo.textContent = &quot;Olá!&quot;;</code></pre>", "errors": ["", "textContent define conteúdo textual. Ele não muda a localização do servidor nem credenciais.", "textContent define conteúdo textual. Ele não muda a localização do servidor nem credenciais."]}, {"intro": "<p>Um listener associa uma função a um evento, como click.</p><pre><code>botao.addEventListener(&quot;click&quot;, calcular);</code></pre>", "errors": ["", "A função é associada ao evento click do botão. O código não cria um temporizador.", "A função é associada ao evento click do botão. O código não cria um temporizador."]}], "web-formularios": [{"intro": "<p>Formulários coletam dados. label identifica um campo; input permite digitação; required solicita preenchimento.</p>", "errors": ["", "O label dá um nome compreensível ao controle e ajuda na acessibilidade.", "O label dá um nome compreensível ao controle e ajuda na acessibilidade."]}, {"intro": "<p>Validação no navegador dá retorno rápido. O servidor também precisa validar os dados, pois uma requisição pode chegar sem passar pela interface.</p>", "errors": ["", "O servidor não pode confiar apenas em verificações do cliente. Dados podem chegar por outros clientes ou requisições diretas.", "O servidor não pode confiar apenas em verificações do cliente. Dados podem chegar por outros clientes ou requisições diretas."]}], "db-atributos": [{"intro": "<p>Um atributo descreve uma entidade. Ele é <strong>simples</strong> quando não é dividido no modelo. É <strong>composto</strong> quando reunimos partes, como endereço dividido em rua, número e cidade.</p>", "errors": ["", "O endereço pode ser dividido em partes relevantes para o modelo. Ser texto ou número não determina sozinho se um atributo é composto.", "O endereço pode ser dividido em partes relevantes para o modelo. Ser texto ou número não determina sozinho se um atributo é composto."]}, {"intro": "<p>A classificação depende do que o sistema precisa guardar. Um nome pode ser tratado como um único texto ou dividido em partes, se as regras exigirem.</p>", "errors": ["", "Nome tem partes identificáveis no modelo, por isso é composto. Isso não significa que uma pessoa tenha vários nomes registrados nesse atributo.", "Nome tem partes identificáveis no modelo, por isso é composto. Isso não significa que uma pessoa tenha vários nomes registrados nesse atributo."]}], "db-multivalorados": [{"intro": "<p>Um atributo de valor único tem um valor por ocorrência. Um atributo <strong>multivalorado</strong> pode ter vários valores para a mesma ocorrência.</p><div class=\"example\">Uma pessoa pode ter os idiomas {português, inglês}. Idiomas é multivalorado nesse modelo.</div>", "errors": ["", "A mesma pessoa pode ter mais de um valor de telefone. Isso caracteriza multivaloração. Vários dígitos em um telefone não significam vários telefones.", "A mesma pessoa pode ter mais de um valor de telefone. Isso caracteriza multivaloração. Vários dígitos em um telefone não significam vários telefones."]}, {"intro": "<p>Um atributo <strong>armazenado</strong> é guardado diretamente. Um atributo <strong>derivado</strong> pode ser calculado a partir de outros dados.</p><div class=\"example\">Data de nascimento é armazenada. Idade pode ser calculada com ela e a data atual.</div>", "errors": ["", "Idade é obtida por cálculo. Data de nascimento é o dado usado nesse cálculo."]}], "db-dominio-null": [{"intro": "<p>O <strong>tipo</strong> indica a natureza de um valor, como inteiro ou texto. O <strong>domínio</strong> estabelece quais valores são aceitos.</p><div class=\"example\">Uma nota pode ser numérica e ter domínio de 0 a 10.</div>", "errors": ["", "11 está fora do intervalo permitido. Zero está dentro do domínio; não significa que o valor esteja ausente.", "11 está fora do intervalo permitido. Zero está dentro do domínio; não significa que o valor esteja ausente."]}, {"intro": "<p>NULL representa ausência de valor. Ele é diferente de zero ou de um texto vazio. Uma chave primária identifica cada registro e não aceita NULL.</p>", "errors": ["", "A identificação precisa ser única e estar presente. Nomes podem se repetir e não são automaticamente boas chaves.", "A identificação precisa ser única e estar presente. Nomes podem se repetir e não são automaticamente boas chaves."]}], "db-fortes-fracas": [{"intro": "<p>Uma entidade forte tem uma chave que a identifica. Uma entidade fraca depende de uma entidade proprietária para sua identificação completa e existência no modelo.</p><div class=\"example\">Um dependente de funcionário pode ser identificado pela combinação do funcionário e de um identificador local do dependente.</div>", "errors": ["", "A dependência de identificação caracteriza a entidade fraca. O número de atributos e o tamanho do nome não determinam isso.", "A dependência de identificação caracteriza a entidade fraca. O número de atributos e o tamanho do nome não determinam isso."]}, {"intro": "<p>Uma chave composta usa mais de um atributo. No exemplo, funcionário_id junto de dependente_numero pode identificar um dependente.</p>", "errors": ["", "O identificador local pode repetir entre funcionários diferentes. A combinação com funcionário_id torna a identificação completa.", "O identificador local pode repetir entre funcionários diferentes. A combinação com funcionário_id torna a identificação completa."]}], "db-relacionamentos": [{"intro": "<p>Relacionamentos ligam entidades e costumam ser descritos por ações. Um relacionamento binário envolve dois tipos de entidade; um ternário envolve três.</p><div class=\"example\">Funcionário trabalha em Projeto: binário.<br>Fornecedor fornece Peça para Projeto: ternário.</div>", "errors": ["", "Ternário significa que três tipos de entidade participam da mesma associação.", "Ternário significa que três tipos de entidade participam da mesma associação."]}, {"intro": "<p>Em um relacionamento recursivo, um mesmo tipo de entidade participa em papéis diferentes.</p><div class=\"example\">Funcionário supervisiona Funcionário: um é supervisor e o outro é supervisionado.</div>", "errors": ["", "O mesmo tipo, Funcionário, aparece nos dois papéis. As outras relações ligam tipos diferentes.", "O mesmo tipo, Funcionário, aparece nos dois papéis. As outras relações ligam tipos diferentes."]}], "db-participacao": [{"intro": "<p>A participação é <strong>total</strong> quando toda ocorrência deve participar do relacionamento. É <strong>parcial</strong> quando a participação não é obrigatória para todas.</p><div class=\"example\">Suponha que todo empréstimo deva ser realizado por um aluno, mas um aluno possa existir sem realizar empréstimos.</div>", "errors": ["", "Todo empréstimo precisa estar ligado a um aluno, então sua participação é total. Isso não obriga todo aluno a ter empréstimos."]}, {"intro": "<p>Analise cada lado separadamente. Um relacionamento pode ter participação total em um lado e parcial no outro.</p>", "errors": ["", "Um aluno pode estar cadastrado sem ter feito empréstimo. Portanto, sua participação é parcial."]}], "alg-testemesa": [{"intro": "<p>O teste de mesa simula um algoritmo passo a passo. Registre os valores das variáveis depois de cada instrução, sem executar no computador.</p><pre><code>x = 2\ny = x + 3\nx = y * 2</code></pre>", "answer": "10", "kind": "decimal", "label": "Sua resposta", "error": "x começa em 2. y recebe 2 + 3 = 5. Depois x recebe 5 * 2 = 10. A alteração de x não faz y ser recalculado."}, {"intro": "<p>Um algoritmo pode ser expresso em pseudocódigo, fluxograma ou linguagem de programação. O pseudocódigo ajuda a organizar a lógica antes da sintaxe de uma linguagem.</p>", "errors": ["", "Primeiro recebemos as entradas, depois processamos e finalmente apresentamos a saída.", "Primeiro recebemos as entradas, depois processamos e finalmente apresentamos a saída."]}], "web-posicionamento": [{"intro": "<p>position: relative mantém o elemento no fluxo e permite deslocá-lo a partir da posição original. position: absolute o retira do fluxo e usa seu bloco de referência para posicionamento.</p><div class=\"example\">Um contêiner com position: relative pode servir de referência para um filho com position: absolute.</div>", "errors": ["", "relative preserva o espaço original no fluxo. absolute e fixed retiram o elemento do fluxo normal.", "relative preserva o espaço original no fluxo. absolute e fixed retiram o elemento do fluxo normal."]}, {"intro": "<p>position: fixed normalmente usa a janela de visualização como referência. z-index ajuda a definir a ordem de sobreposição, dentro das regras de empilhamento.</p>", "errors": ["", "position: fixed permite posicionar em relação à janela no caso usual. color e font-size não aceitam fixed para essa finalidade.", "position: fixed permite posicionar em relação à janela no caso usual. color e font-size não aceitam fixed para essa finalidade."]}], "web-funcoes": [{"intro": "<p>Uma função reúne instruções. Parâmetros recebem os dados da chamada e return devolve o resultado.</p><pre><code>function soma(a, b) {\n  return a + b;\n}\nconst total = soma(4, 3);</code></pre>", "answer": "7", "kind": "decimal", "label": "Sua resposta", "error": "A chamada fornece a=4 e b=3. return devolve 4 + 3 = 7, guardado em total."}, {"intro": "<p>O evento de clique pode chamar uma função que lê campos, converte os valores e atualiza o resultado.</p><div class=\"example\">Valores de campos de texto são strings. Number(\"4\") produz o número 4.</div>", "errors": ["", "O operador + pode concatenar strings. A conversão permite somar números e obter 7, em vez do texto \"43\".", "O operador + pode concatenar strings. A conversão permite somar números e obter 7, em vez do texto \"43\"."]}], "db-cardinalidade": [{"intro": "<p>Cardinalidade indica quantas ocorrências podem se relacionar. Suponha: um cliente pode ter muitos pedidos, e cada pedido pertence a um único cliente.</p>", "errors": ["", "Um cliente para muitos pedidos é 1:N. N:N exigiria que cada pedido também pudesse pertencer a vários clientes.", "Um cliente para muitos pedidos é 1:N. N:N exigiria que cada pedido também pudesse pertencer a vários clientes."]}, {"intro": "<p>Um aluno pode cursar várias disciplinas e uma disciplina pode ter vários alunos. Uma relação N:N costuma ser representada por uma tabela associativa no modelo relacional.</p>", "errors": ["", "Matricula guarda as referências às duas entidades e representa cada associação.", "Matricula guarda as referências às duas entidades e representa cada associação."]}], "db-estendido": [{"intro": "<p>Especialização divide uma entidade geral em tipos mais específicos. Por exemplo, Pessoa pode ter os subtipos Aluno e Professor. Os subtipos compartilham atributos da entidade geral.</p>", "errors": ["", "Pessoa é a entidade geral. Aluno e Professor são tipos específicos de Pessoa.", "Pessoa é a entidade geral. Aluno e Professor são tipos específicos de Pessoa."]}, {"intro": "<p>Na especialização <strong>disjunta</strong>, uma ocorrência não pode pertencer simultaneamente a mais de um subtipo. Na sobreposta, isso pode acontecer, conforme as regras do domínio.</p>", "errors": ["", "A participação simultânea em dois subtipos caracteriza sobreposição."]}], "db-relacional": [{"intro": "<p>Uma tabela guarda linhas (registros) e colunas (atributos). A chave primária identifica cada linha de forma única e não admite NULL.</p>", "errors": ["", "A chave precisa distinguir cada aluno. Nome e idade podem se repetir.", "A chave precisa distinguir cada aluno. Nome e idade podem se repetir."]}, {"intro": "<p>Uma chave estrangeira referencia uma chave de outra tabela. Em Pedido(cliente_id), cliente_id pode apontar para Cliente(id).</p>", "errors": ["", "A referência liga cada pedido ao cliente correspondente e permite verificar integridade referencial.", "A referência liga cada pedido ao cliente correspondente e permite verificar integridade referencial."]}], "db-algebra": [{"intro": "<p>Na álgebra relacional, <strong>seleção</strong> filtra linhas por condição; <strong>projeção</strong> escolhe atributos (colunas).</p><div class=\"example\">Selecionar alunos com idade maior que 18 filtra registros. Projetar apenas nome escolhe uma coluna.</div>", "errors": ["", "Projeção escolhe atributos. Seleção determina quais linhas satisfazem uma condição.", "Projeção escolhe atributos. Seleção determina quais linhas satisfazem uma condição."]}, {"intro": "<p>Uma junção combina registros de relações diferentes usando uma condição, como igualdade de chaves.</p>", "errors": ["", "A chave estrangeira do pedido deve corresponder ao identificador do cliente.", "A chave estrangeira do pedido deve corresponder ao identificador do cliente."]}], "db-ddl": [{"intro": "<p>DDL define estruturas: CREATE TABLE cria uma tabela, ALTER TABLE altera a estrutura e DROP TABLE remove a tabela.</p>", "errors": ["", "CREATE TABLE define a estrutura. INSERT insere linhas e SELECT consulta dados.", "CREATE TABLE define a estrutura. INSERT insere linhas e SELECT consulta dados."]}, {"intro": "<p>Uma definição simples de tabela pode declarar tipos e restrições.</p><pre><code>CREATE TABLE Aluno (\n  id INTEGER PRIMARY KEY,\n  nome VARCHAR(100) NOT NULL\n);</code></pre>", "errors": ["", "NOT NULL proíbe ausência de valor. Não exige unicidade nem comprimento exato.", "NOT NULL proíbe ausência de valor. Não exige unicidade nem comprimento exato."]}], "db-dml": [{"intro": "<p>INSERT adiciona registros; UPDATE altera registros; DELETE remove registros. Esses comandos modificam os dados, não a estrutura da tabela.</p><pre><code>INSERT INTO Aluno (id, nome) VALUES (1, &#x27;Ana&#x27;);</code></pre>", "errors": ["", "INSERT INTO adiciona uma linha à tabela existente. As colunas e os valores se correspondem pela ordem.", "INSERT INTO adiciona uma linha à tabela existente. As colunas e os valores se correspondem pela ordem."]}, {"intro": "<p>WHERE restringe quais linhas serão alteradas. Sem WHERE, um UPDATE pode afetar todas as linhas da tabela.</p>", "errors": ["", "O WHERE id = 1 limita a alteração. A segunda opção altera todos os nomes, e DELETE remove registros.", "O WHERE id = 1 limita a alteração. A segunda opção altera todos os nomes, e DELETE remove registros."]}], "db-minmax": [{"intro": "<p>Cardinalidade máxima responde quantas associações são permitidas. A mínima indica se a participação é obrigatória.</p><div class=\"example\">0..N: nenhuma ou várias associações.<br>1..N: pelo menos uma.<br>0..1: nenhuma ou uma.<br>1..1: exatamente uma.</div>", "errors": ["", "A ausência de pedidos é permitida, então o mínimo é 0. Vários pedidos são permitidos, então o máximo é N.", "A ausência de pedidos é permitida, então o mínimo é 0. Vários pedidos são permitidos, então o máximo é N."]}, {"intro": "<p>Analise a regra nos dois sentidos. Suponha que cada pedido pertença obrigatoriamente a um único cliente.</p>", "errors": ["", "A associação é obrigatória e única: mínimo 1 e máximo 1. Isso não limita a quantidade de pedidos do cliente.", "A associação é obrigatória e única: mínimo 1 e máximo 1. Isso não limita a quantidade de pedidos do cliente."]}], "db-completude": [{"intro": "<p>Uma subclasse herda os atributos e relacionamentos da superclasse e pode ter características específicas.</p><div class=\"example\">Funcionário tem nome. Engenheiro é um subtipo e acrescenta tipo de engenharia.</div>", "errors": ["", "Engenheiro herda o atributo nome de Funcionário. O subtipo acrescenta seus atributos específicos.", "Engenheiro herda o atributo nome de Funcionário. O subtipo acrescenta seus atributos específicos."]}, {"intro": "<p>Uma especialização é <strong>total</strong> quando toda ocorrência da superclasse pertence a pelo menos uma subclasse. É <strong>parcial</strong> quando alguma pode não pertencer a nenhuma.</p><p>Essa regra é independente de disjunção ou sobreposição.</p>", "errors": ["", "Toda ocorrência foi coberta pelos subtipos: a especialização é total. A regra não diz, sozinha, se é permitido pertencer a mais de um subtipo.", "Toda ocorrência foi coberta pelos subtipos: a especialização é total. A regra não diz, sozinha, se é permitido pertencer a mais de um subtipo."]}], "db-map-1n": [{"intro": "<p>Em uma relação 1:N, uma implementação usual coloca a chave estrangeira na tabela do lado N.</p><div class=\"example\">Um Departamento possui vários Funcionários. Cada Funcionário pertence a um Departamento.</div>", "errors": ["", "Cada funcionário precisa apontar para um departamento. A FK fica no lado N e referencia a chave do departamento.", "Cada funcionário precisa apontar para um departamento. A FK fica no lado N e referencia a chave do departamento."]}, {"intro": "<p>Se todo funcionário precisa de departamento, a FK pode ser NOT NULL. A chave estrangeira verifica a referência; NOT NULL exige que ela esteja preenchida.</p>", "errors": ["", "São duas regras diferentes: a FK garante a referência válida e NOT NULL proíbe ausência de valor.", "São duas regras diferentes: a FK garante a referência válida e NOT NULL proíbe ausência de valor."]}], "db-map-mn": [{"intro": "<p>Uma relação N:N costuma virar uma tabela associativa com referências para os dois lados. A combinação dessas referências pode formar a chave primária.</p><div class=\"example\">Aluno cursa Disciplina → Matricula(aluno_id, disciplina_id).</div>", "errors": ["", "A associativa guarda cada vínculo entre um aluno e uma disciplina. Uma lista em um único campo dificulta representar os registros relacionais.", "A associativa guarda cada vínculo entre um aluno e uma disciplina. Uma lista em um único campo dificulta representar os registros relacionais."]}, {"intro": "<p>Um atributo do relacionamento vai para a tabela que representa a associação.</p><div class=\"example\">A nota pertence à matrícula do aluno em uma disciplina.</div>", "errors": ["", "A nota depende do par aluno–disciplina. Por isso é atributo da associação e fica em Matricula.", "A nota depende do par aluno–disciplina. Por isso é atributo da associação e fica em Matricula."]}], "db-map-multivalorado": [{"intro": "<p>Um atributo multivalorado pode virar uma tabela própria com o identificador da entidade e um valor por linha.</p><div class=\"example\">Cliente(id, nome)<br>Telefone(cliente_id, numero)</div>", "errors": ["", "A referência ao cliente se repete, mas cada linha guarda um telefone. Não precisamos duplicar o cadastro do cliente.", "A referência ao cliente se repete, mas cada linha guarda um telefone. Não precisamos duplicar o cadastro do cliente."]}, {"intro": "<p>A chave pode combinar o identificador da entidade e o valor do atributo, quando essa combinação satisfizer as regras do domínio.</p>", "errors": ["", "cliente_id sozinho impediria vários telefones. A combinação distingue os valores de cada cliente.", "cliente_id sozinho impediria vários telefones. A combinação distingue os valores de cada cliente."]}], "db-map-heranca": [{"intro": "<p>Uma estratégia cria uma tabela para a superclasse e uma para cada subclasse. A chave da subclasse também referencia a superclasse.</p><div class=\"example\">Funcionario(id, nome)<br>Engenheiro(id, tipo)<br>Engenheiro.id → Funcionario.id</div>", "errors": ["", "id identifica o engenheiro e o liga ao funcionário correspondente. A mesma coluna pode ser PK e FK.", "id identifica o engenheiro e o liga ao funcionário correspondente. A mesma coluna pode ser PK e FK."]}, {"intro": "<p>Há outras estratégias: uma tabela com discriminador para subtipos disjuntos, ou indicadores booleanos para sobreposição. Usar apenas tabelas das subclasses exige especialização total para não perder ocorrências da superclasse.</p>", "errors": ["", "Na especialização parcial, uma ocorrência da superclasse pode não pertencer a nenhuma subclasse. Sem tabela da superclasse, ela poderia não ser representada.", "Na especialização parcial, uma ocorrência da superclasse pode não pertencer a nenhuma subclasse. Sem tabela da superclasse, ela poderia não ser representada."]}], "db-produto": [{"intro": "<p>O produto cartesiano combina cada linha de uma relação com cada linha da outra. Com m e n linhas, o resultado tem m × n linhas.</p>", "answer": "6", "kind": "decimal", "label": "Sua resposta", "error": "Cada uma das 3 linhas combina com as 2 da outra relação: 3 × 2 = 6."}, {"intro": "<p>O produto sozinho pode criar combinações que não representam vínculos reais. Para relacionar Pedido a Cliente, selecione os pares cujos identificadores correspondem.</p>", "errors": ["", "O vínculo é dado pela referência ao identificador do cliente. Sem a condição, todos os pares permanecem.", "O vínculo é dado pela referência ao identificador do cliente. Sem a condição, todos os pares permanecem."]}], "db-uniao": [{"intro": "<p>A união reúne as tuplas de duas relações compatíveis e elimina duplicatas na álgebra relacional clássica. É preciso ter o mesmo número de atributos e domínios compatíveis nas posições correspondentes.</p>", "errors": ["", "A compatibilidade depende da estrutura das relações, não da aparência ou do nome das tabelas.", "A compatibilidade depende da estrutura das relações, não da aparência ou do nome das tabelas."]}, {"intro": "<p>Pense em relações como conjuntos, sem duplicatas.</p><div class=\"example\">A = {1, 2}<br>B = {2, 3}</div>", "answer": "3", "kind": "decimal", "label": "Sua resposta", "error": "A união contém {1, 2, 3}. O 2 aparece apenas uma vez no conjunto resultante."}], "db-diferenca": [{"intro": "<p>A − B mantém as tuplas que estão em A e não estão em B. A ordem importa.</p><div class=\"example\">A = {1, 2, 3}<br>B = {2, 3, 4}</div>", "errors": ["", "1 está em A e não está em B. {4} seria B − A, e {2, 3} seria a interseção.", "1 está em A e não está em B. {4} seria B − A, e {2, 3} seria a interseção."]}, {"intro": "<p>A ∩ B mantém apenas as tuplas presentes nas duas relações.</p><div class=\"example\">A = {1, 2, 3}<br>B = {2, 3, 4}</div>", "errors": ["", "2 e 3 pertencem aos dois conjuntos. Reunir todos os valores faria a união.", "2 e 3 pertencem aos dois conjuntos. Reunir todos os valores faria a união."]}], "db-juncao-renomear": [{"intro": "<p>A junção natural combina linhas com valores iguais nos atributos de mesmo nome e apresenta uma única cópia desses atributos comuns.</p><div class=\"example\">Se as relações compartilham apenas cliente_id, esse atributo define a correspondência.</div>", "errors": ["", "A junção natural usa todos os atributos de mesmo nome. É necessário conferir os esquemas para não impor condições indesejadas.", "A junção natural usa todos os atributos de mesmo nome. É necessário conferir os esquemas para não impor condições indesejadas."]}, {"intro": "<p>Renomear uma relação permite distinguir duas ocorrências dela na mesma consulta.</p><div class=\"example\">Para comparar funcionários entre si, podemos usar F1 e F2 como nomes diferentes da relação Funcionario.</div>", "errors": ["", "A renomeação resolve a ambiguidade entre os dois papéis. Ela não altera os valores dos registros.", "A renomeação resolve a ambiguidade entre os dois papéis. Ela não altera os valores dos registros."]}], "db-divisao": [{"intro": "<p>A divisão relacional aparece em perguntas com <strong>“todos”</strong>.</p><div class=\"example\">AlunoDisciplina contém (Ana, BD), (Ana, Web) e (Bia, BD). Disciplinas exigidas = {BD, Web}.</div>", "errors": ["", "Ana tem BD e Web. Bia tem apenas BD, então não satisfaz a condição para todas as disciplinas.", "Ana tem BD e Web. Bia tem apenas BD, então não satisfaz a condição para todas as disciplinas."]}, {"intro": "<p>Uma atribuição armazena o resultado de uma operação em uma relação temporária para reutilização.</p><div class=\"example\">T ← seleção de alunos ativos.</div>", "errors": ["", "T guarda o resultado intermediário. A atribuição da álgebra não equivale a um UPDATE nos dados originais.", "T guarda o resultado intermediário. A atribuição da álgebra não equivale a um UPDATE nos dados originais."]}], "db-tipos": [{"intro": "<p>Escolha o tipo conforme o dado: INTEGER para contagens, VARCHAR para texto com limite, DATE para datas e NUMERIC(p,s) para decimais com precisão e escala definidas.</p>", "errors": ["", "NUMERIC(10,2) é um tipo decimal exato com escala 2. Ponto flutuante pode introduzir aproximações, e DATE guarda datas.", "NUMERIC(10,2) é um tipo decimal exato com escala 2. Ponto flutuante pode introduzir aproximações, e DATE guarda datas."]}, {"intro": "<p>Um schema organiza objetos dentro do banco. O nome schema.tabela identifica a tabela nesse espaço.</p><div class=\"example\">CREATE SCHEMA estudos;<br>CREATE TABLE estudos.aluno (...);</div>", "errors": ["", "estudos identifica o schema que contém a tabela aluno.", "estudos identifica o schema que contém a tabela aluno."]}], "db-restricoes": [{"intro": "<p>CHECK impõe uma condição aos valores; DEFAULT fornece um valor quando a coluna é omitida na inserção; UNIQUE impõe unicidade.</p><pre><code>quantidade INTEGER DEFAULT 0 CHECK (quantidade &gt;= 0)</code></pre>", "errors": ["", "A condição exige quantidade maior ou igual a zero. DEFAULT não transforma automaticamente um valor negativo em zero.", "A condição exige quantidade maior ou igual a zero. DEFAULT não transforma automaticamente um valor negativo em zero."]}, {"intro": "<p>DEFAULT é aplicado quando usamos o padrão ou omitimos a coluna. Ele não substitui automaticamente um NULL explícito.</p><pre><code>status VARCHAR(20) DEFAULT &#x27;Pendente&#x27;</code></pre>", "errors": ["", "A definição estabelece Pendente como padrão para a coluna omitida.", "A definição estabelece Pendente como padrão para a coluna omitida."]}], "db-alter-drop": [{"intro": "<p>CREATE TABLE cria a estrutura. ALTER TABLE modifica a estrutura existente. DROP TABLE remove a tabela.</p>", "errors": ["", "ADD COLUMN em ALTER TABLE modifica o esquema. UPDATE altera dados e DELETE remove linhas.", "ADD COLUMN em ALTER TABLE modifica o esquema. UPDATE altera dados e DELETE remove linhas."]}, {"intro": "<p>Uma FOREIGN KEY liga uma coluna a uma chave referenciada. Ao criar tabelas com essa dependência, a tabela referenciada normalmente precisa existir primeiro.</p>", "errors": ["", "A tabela cliente fornece o alvo da referência. Depois criamos pedido com a FK.", "A tabela cliente fornece o alvo da referência. Depois criamos pedido com a FK."]}], "db-insert-fk": [{"intro": "<p>Uma FK preenchida precisa corresponder a um valor existente na chave referenciada, salvo regras específicas de adiamento da verificação. Neste exercício, a verificação é imediata.</p><div class=\"example\">Cliente tem apenas id=1. Pedido.cliente_id referencia Cliente.id.</div>", "errors": ["", "Não existe cliente 99 para satisfazer a referência. Uma FK não cria o registro pai automaticamente.", "Não existe cliente 99 para satisfazer a referência. Uma FK não cria o registro pai automaticamente."]}, {"intro": "<p>No caso usual com verificação imediata, insira primeiro o registro pai e depois o filho que o referencia.</p>", "errors": ["", "O cliente precisa existir quando o pedido for verificado.", "O cliente precisa existir quando o pedido for verificado."]}], "db-delete": [{"intro": "<p>DELETE remove linhas. WHERE determina quais serão removidas. Sem WHERE, o comando solicita a remoção de todas as linhas da tabela.</p>", "errors": ["", "O filtro identifica a linha. DELETE sem filtro solicita todas as linhas; DROP remove a estrutura da tabela.", "O filtro identifica a linha. DELETE sem filtro solicita todas as linhas; DROP remove a estrutura da tabela."]}, {"intro": "<p>Uma exclusão pode ser impedida por referências de outras tabelas. Considere uma FK com comportamento padrão e pedidos que ainda apontam para um cliente.</p>", "errors": ["", "A integridade referencial protege os vínculos. O efeito exato depende da ação definida na FK.", "A integridade referencial protege os vínculos. O efeito exato depende da ação definida na FK."]}], "db-select": [{"intro": "<p>SELECT escolhe colunas, FROM informa a tabela e WHERE filtra linhas. A consulta permite conferir os resultados depois de INSERT, UPDATE ou DELETE.</p>", "errors": ["", "A primeira opção escolhe nome e aplica o filtro id=2. UPDATE altera dados e a última consulta escolhe outra coluna sem filtro.", "A primeira opção escolhe nome e aplica o filtro id=2. UPDATE altera dados e a última consulta escolhe outra coluna sem filtro."]}, {"intro": "<p>Considere a tabela abaixo:</p><table><tr><th>id</th><th>idade</th></tr><tr><td>1</td><td>17</td></tr><tr><td>2</td><td>20</td></tr><tr><td>3</td><td>22</td></tr></table><div class=\"example\">SELECT * FROM aluno WHERE idade >= 20;</div>", "answer": "2", "kind": "decimal", "label": "Sua resposta", "error": "As idades 20 e 22 satisfazem >= 20. A linha com idade 17 fica de fora."}]});
LESSONS.sort((a,b)=>COURSES.findIndex(c=>c.id===a.course)-COURSES.findIndex(c=>c.id===b.course)||a.group.localeCompare(b.group,"pt-BR"));
